const IB_SETS = {"morning":[{"t":"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ\nاللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ. [آيَةُ الْكُرْسِيِّ - الْبَقَرَةُ 255].","c":1,"v":"مَنْ قَالَهَا حِينَ يُصْبِحُ أُجِيرَ مِنَ الْجِنِّ حَتَّى يُمْسِيَ وَمَنْ قَالَهَا حِينَ يُمْسِي أُجِيرَ مِنَ الْجِنِّ حَتَّى يُصْبِحَ.","s":"رواه النسائي في عمل اليوم والليلة والحاكم من حديث أُبيّ بن كعب، وصححه الألباني"},{"t":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\nقُلْ هُوَ اللَّهُ أَحَدٌ، اللَّهُ الصَّمَدُ، لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ.","c":3,"v":"مَنْ قَالَهَا حِينَ يُصْبِحُ وَحِينَ يُمْسِي كَفَتْهُ مِنْ كُلِّ شَيْءٍ (الْإِخْلَاصِ وَالْمُعَوِّذَتَيْنِ).","s":"رواه أبو داود والترمذي من حديث عبد الله بن خُبيب، وحسّنه الألباني"},{"t":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ، مِن شَرِّ مَا خَلَقَ، وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ، وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ، وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ.","c":3,"s":"رواه أبو داود والترمذي من حديث عبد الله بن خُبيب، وحسّنه الألباني"},{"t":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ النَّاسِ، مَلِكِ النَّاسِ، إِلَٰهِ النَّاسِ، مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ، الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ، مِنَ الْجِنَّةِ وَالنَّاسِ.","c":3,"s":"رواه أبو داود والترمذي من حديث عبد الله بن خُبيب، وحسّنه الألباني"},{"t":"أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ وَالْحَمْدُ لِلَّهِ ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ.","c":1,"s":"رواه مسلم"},{"t":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ ، خَلَقْتَنِي وَأَنَا عَبْدُكَ ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ .","c":1,"v":"مَنْ قَالَهَا مُوقِنًا بِهَا حِينَ يُمْسِي وَمَاتَ مِنْ لَيْلَتِهِ دَخَلَ الْجَنَّةَ وَكَذَلِكَ حِينَ يُصْبِحُ.","s":"رواه البخاري"},{"t":"رَضِيتُ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا وَبِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا.","c":3,"v":"مَنْ قَالَهَا حِينَ يُصْبِحُ وَحِينَ يُمْسِي كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُرْضِيَهُ يَوْمَ الْقِيَامَةِ.","s":"رواه أبو داود والترمذي","f":"disp","w":"مختلف في ثبوت هذا الفضل بهذا العدد: حسّنه بعض العلماء وضعّفه آخرون (منهم الألباني). وأصل «رضيت بالله ربًا…» صحيح عند مسلم في غير هذا الموضع."},{"t":"اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ ، وَمَلَائِكَتَكَ ، وَجَمِيعَ خَلْقِكَ ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ.","c":4,"v":"مَنْ قَالَهَا أَعْتَقَهُ اللَّهُ مِنَ النَّارِ.","s":"رواه أبو داود","f":"weak","w":"إسناده ضعيف — ضعّفه الألباني (ضعيف أبي داود)"},{"t":"اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ ، فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ.","c":1,"v":"مَنْ قَالَهَا حِينَ يُصْبِحُ أَدَّى شُكْرَ يَوْمِهِ.","s":"رواه أبو داود","f":"weak","w":"إسناده ضعيف — ضعّفه الألباني (ضعيف أبي داود)"},{"t":"حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ.","c":7,"v":"مَنْ قَالَهَا كَفَاهُ اللَّهُ مَا أَهَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ.","s":"رواه أبو داود موقوفًا على أبي الدرداء","f":"weak","w":"لا يصح مرفوعًا إلى النبي ﷺ، والفضل المذكور لم يثبت — ضعّفه الألباني"},{"t":"بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ.","c":3,"v":"لَمْ يَضُرَّهُ مِنَ اللَّهِ شَيْءٌ.","s":"رواه أبو داود والترمذي وابن ماجه من حديث عثمان بن عفان، وصححه الألباني"},{"t":"اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا ، وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ.","c":1,"s":"رواه أبو داود والترمذي، وصححه الألباني"},{"t":"أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ.","c":1,"s":"رواه أحمد والنسائي في عمل اليوم والليلة، وصححه الألباني"},{"t":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ عَدَدَ خَلْقِهِ ، وَرِضَا نَفْسِهِ ، وَزِنَةَ عَرْشِهِ ، وَمِدَادَ كَلِمَاتِهِ.","c":3,"s":"رواه مسلم من حديث جويرية رضي الله عنها"},{"t":"اللَّهُمَّ عَافِنِي فِي بَدَنِي ، اللَّهُمَّ عَافِنِي فِي سَمْعِي ، اللَّهُمَّ عَافِنِي فِي بَصَرِي ، لَا إِلَهَ إِلَّا أَنْتَ.","c":3,"s":"رواه أبو داود وأحمد من حديث أبي بكرة، وحسّنه الألباني"},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ ، وَالْفَقْرِ ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ ، لَا إِلَهَ إِلَّا أَنْتَ.","c":3,"s":"رواه أبو داود من حديث أبي بكرة، وحسّنه الألباني"},{"t":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي ، اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي ، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي ، وَمِنْ فَوْقِي ، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.","c":1,"s":"رواه أبو داود وابن ماجه من حديث ابن عمر، وصححه الألباني"},{"t":"يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ أَصْلِحْ لِي شَأْنِي كُلَّهُ وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ.","c":3,"s":"رواه النسائي في الكبرى والحاكم من حديث أنس، وحسّنه الألباني (صحيح الترغيب 661)"},{"t":"أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ ، فَتْحَهُ ، وَنَصْرَهُ ، وَنُورَهُ وَبَرَكَتَهُ ، وَهُدَاهُ ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهِ وَشَرِّ مَا بَعْدَهُ.","c":1,"s":"رواه أبو داود","f":"disp","w":"مختلف في ثبوته: في إسناده مقال، وضعّفه بعض المحققين"},{"t":"اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ.","c":1,"s":"رواه أبو داود والترمذي من حديث أبي هريرة، وصححه الألباني"},{"t":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ.","c":3,"s":"رواه مسلم، وقولها ثلاثًا عند المساء عند أحمد والترمذي، وصححه الألباني"},{"t":"اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ أَنْ نُشْرِكَ بِكَ شَيْئًا نَعْلَمُهُ ، وَنَسْتَغْفِرُكَ لِمَا لَا نَعْلَمُهُ.","c":3,"s":"رواه أحمد من حديث أبي موسى، وصححه الألباني لغيره (صحيح الترغيب 36)"},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ.","c":3,"s":"رواه البخاري من حديث أنس"},{"t":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ، الْحَيَّ الْقَيُّومَ، وَأَتُوبُ إِلَيْهِ.","c":3,"s":"رواه أبو داود والترمذي، وصححه الألباني"},{"t":"يَا رَبِّ , لَكَ الْحَمْدُ كَمَا يَنْبَغِي لِجَلَالِ وَجْهِكَ , وَلِعَظِيمِ سُلْطَانِكَ.","c":3,"s":"رواه ابن ماجه","f":"weak","w":"إسناده ضعيف — ضعّفه الألباني (ضعيف ابن ماجه)"},{"t":"اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا.","c":1,"s":"رواه ابن ماجه وأحمد من حديث أم سلمة (بعد صلاة الصبح)، وصححه الألباني"},{"t":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ ، عَلَيْكَ تَوَكَّلْتُ ، وَأَنْتَ رَبُّ الْعَرْشِ الْعَظِيمِ , مَا شَاءَ اللَّهُ كَانَ ، وَمَا لَمْ يَشَأْ لَمْ يَكُنْ ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ , أَعْلَمُ أَنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ، وَأَنَّ اللَّهَ قَدْ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا , اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي ، وَمِنْ شَرِّ كُلِّ دَابَّةٍ أَنْتَ آخِذٌ بِنَاصِيَتِهَا ، إِنَّ رَبِّي عَلَى صِرَاطٍ مُسْتَقِيمٍ.","c":1,"v":"ذِكْرٌ طَيِّبٌ.","s":"رواه ابن السني","f":"weak","w":"إسناده ضعيف جدًا — لا يثبت عن النبي ﷺ"},{"t":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى نَبِيِّنَا مُحَمَّدٍ.","c":10,"v":"مَنْ صَلَّى عَلَيَّ حِينَ يُصْبِحُ وَحِينَ يُمْسِي أَدْرَكَتْهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ.","s":"رواه الطبراني","f":"weak","w":"الفضل المذكور («أدركته شفاعتي») إسناده ضعيف على الأرجح. والصلاة على النبي ﷺ مشروعة في كل وقت: «من صلى علي صلاة صلى الله عليه بها عشرًا» — رواه مسلم"},{"t":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.","c":100,"v":"كَانَتْ لَهُ عَدْلَ عَشْرِ رِقَابٍ، وَكُتِبَتْ لَهُ مِئَةُ حَسَنَةٍ، وَمُحِيَتْ عَنْهُ مِئَةُ سَيِّئَةٍ، وَكَانَتْ لَهُ حِرْزًا مِنَ الشَّيْطَانِ.","s":"متفق عليه من حديث أبي هريرة"},{"t":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ.","c":100,"v":"حُطَّتْ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ. لَمْ يَأْتِ أَحَدٌ يَوْمَ الْقِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلَّا أَحَدٌ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَيْهِ.","s":"رواه مسلم، وأصله متفق عليه"},{"t":"أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ","c":100,"v":"قال رسول الله ﷺ: «يا أيها الناس توبوا إلى الله، فإني أتوب في اليوم إليه مائة مرة»","s":"رواه مسلم من حديث الأغرّ المزني، وعند البخاري: «أكثر من سبعين مرة»"}],"evening":[{"t":"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ\nاللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ. [آيَةُ الْكُرْسِيِّ - الْبَقَرَةُ 255].","c":1,"v":"مَنْ قَالَهَا حِينَ يُصْبِحُ أُجِيرَ مِنَ الْجِنِّ حَتَّى يُمْسِيَ وَمَنْ قَالَهَا حِينَ يُمْسِي أُجِيرَ مِنَ الْجِنِّ حَتَّى يُصْبِحَ.","s":"رواه النسائي في عمل اليوم والليلة والحاكم من حديث أُبيّ بن كعب، وصححه الألباني"},{"t":"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ\nآمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ. لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ. [الْبَقَرَةُ 285 - 286].","c":1,"v":"مَنْ قَرَأَ آيَتَيْنِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ.","s":"متفق عليه من حديث أبي مسعود الأنصاري"},{"t":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\nقُلْ هُوَ اللَّهُ أَحَدٌ، اللَّهُ الصَّمَدُ، لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ.","c":3,"v":"مَنْ قَالَهَا حِينَ يُصْبِحُ وَحِينَ يُمْسِي كَفَتْهُ مِنْ كُلِّ شَيْءٍ (الْإِخْلَاصِ وَالْمُعَوِّذَتَيْنِ).","s":"رواه أبو داود والترمذي من حديث عبد الله بن خُبيب، وحسّنه الألباني"},{"t":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ، مِن شَرِّ مَا خَلَقَ، وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ، وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ، وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ.","c":3,"s":"رواه أبو داود والترمذي من حديث عبد الله بن خُبيب، وحسّنه الألباني"},{"t":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ النَّاسِ، مَلِكِ النَّاسِ، إِلَٰهِ النَّاسِ، مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ، الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ، مِنَ الْجِنَّةِ وَالنَّاسِ.","c":3,"s":"رواه أبو داود والترمذي من حديث عبد الله بن خُبيب، وحسّنه الألباني"},{"t":"أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ وَالْحَمْدُ لِلَّهِ ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ.","c":1,"s":"رواه مسلم"},{"t":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ ، خَلَقْتَنِي وَأَنَا عَبْدُكَ ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ .","c":1,"v":"مَنْ قَالَهَا مُوقِنًا بِهَا حِينَ يُمْسِي وَمَاتَ مِنْ لَيْلَتِهِ دَخَلَ الْجَنَّةَ وَكَذَلِكَ حِينَ يُصْبِحُ.","s":"رواه البخاري"},{"t":"رَضِيتُ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا وَبِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا.","c":3,"v":"مَنْ قَالَهَا حِينَ يُصْبِحُ وَحِينَ يُمْسِي كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُرْضِيَهُ يَوْمَ الْقِيَامَةِ.","s":"رواه أبو داود والترمذي","f":"disp","w":"مختلف في ثبوت هذا الفضل بهذا العدد: حسّنه بعض العلماء وضعّفه آخرون (منهم الألباني). وأصل «رضيت بالله ربًا…» صحيح عند مسلم في غير هذا الموضع."},{"t":"اللَّهُمَّ إِنِّي أَمْسَيْتُ أُشْهِدُكَ ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ ، وَمَلَائِكَتَكَ ، وَجَمِيعَ خَلْقِكَ ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ.","c":4,"v":"مَنْ قَالَهَا أَعْتَقَهُ اللَّهُ مِنَ النَّارِ.","s":"رواه أبو داود","f":"weak","w":"إسناده ضعيف — ضعّفه الألباني (ضعيف أبي داود)"},{"t":"اللَّهُمَّ مَا أَمْسَى بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ ، فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ.","c":1,"v":"مَنْ قَالَهَا حِينَ يُمْسِي أَدَّى شُكْرَ يَوْمِهِ.","s":"رواه أبو داود","f":"weak","w":"إسناده ضعيف — ضعّفه الألباني (ضعيف أبي داود)"},{"t":"حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ.","c":7,"v":"مَنْ قَالَهَا كَفَاهُ اللَّهُ مَا أَهَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ.","s":"رواه أبو داود موقوفًا على أبي الدرداء","f":"weak","w":"لا يصح مرفوعًا إلى النبي ﷺ، والفضل المذكور لم يثبت — ضعّفه الألباني"},{"t":"بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ.","c":3,"v":"لَمْ يَضُرَّهُ مِنَ اللَّهِ شَيْءٌ.","s":"رواه أبو داود والترمذي وابن ماجه من حديث عثمان بن عفان، وصححه الألباني"},{"t":"اللَّهُمَّ بِكَ أَمْسَيْنَا وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ الْمَصِيرُ.","c":1,"s":"رواه أبو داود والترمذي، وصححه الألباني"},{"t":"أَمْسَيْنَا عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ.","c":1,"s":"رواه أحمد والنسائي في عمل اليوم والليلة، وصححه الألباني"},{"t":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ عَدَدَ خَلْقِهِ ، وَرِضَا نَفْسِهِ ، وَزِنَةَ عَرْشِهِ ، وَمِدَادَ كَلِمَاتِهِ.","c":3,"s":"رواه مسلم من حديث جويرية رضي الله عنها"},{"t":"اللَّهُمَّ عَافِنِي فِي بَدَنِي ، اللَّهُمَّ عَافِنِي فِي سَمْعِي ، اللَّهُمَّ عَافِنِي فِي بَصَرِي ، لَا إِلَهَ إِلَّا أَنْتَ.","c":3,"s":"رواه أبو داود وأحمد من حديث أبي بكرة، وحسّنه الألباني"},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ ، وَالْفَقْرِ ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ ، لَا إِلَهَ إِلَّا أَنْتَ.","c":3,"s":"رواه أبو داود من حديث أبي بكرة، وحسّنه الألباني"},{"t":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي ، اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي ، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي ، وَمِنْ فَوْقِي ، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.","c":1,"s":"رواه أبو داود وابن ماجه من حديث ابن عمر، وصححه الألباني"},{"t":"يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ أَصْلِحْ لِي شَأْنِي كُلَّهُ وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ.","c":3,"s":"رواه النسائي في الكبرى والحاكم من حديث أنس، وحسّنه الألباني (صحيح الترغيب 661)"},{"t":"أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذِهِ اللَّيْلَةِ فَتْحَهَا وَنَصْرَهَا، وَنُورَهَا وَبَرَكَتَهَا، وَهُدَاهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهَا وَشَرِّ مَا بَعْدَهَا.","c":1,"s":"رواه أبو داود","f":"disp","w":"مختلف في ثبوته: في إسناده مقال، وضعّفه بعض المحققين"},{"t":"اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ.","c":1,"s":"رواه أبو داود والترمذي من حديث أبي هريرة، وصححه الألباني"},{"t":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ.","c":3,"s":"رواه مسلم، وقولها ثلاثًا عند المساء عند أحمد والترمذي، وصححه الألباني"},{"t":"اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ أَنْ نُشْرِكَ بِكَ شَيْئًا نَعْلَمُهُ ، وَنَسْتَغْفِرُكَ لِمَا لَا نَعْلَمُهُ.","c":3,"s":"رواه أحمد من حديث أبي موسى، وصححه الألباني لغيره (صحيح الترغيب 36)"},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ.","c":3,"s":"رواه البخاري من حديث أنس"},{"t":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ، الْحَيَّ الْقَيُّومَ، وَأَتُوبُ إِلَيْهِ.","c":3,"s":"رواه أبو داود والترمذي، وصححه الألباني"},{"t":"يَا رَبِّ , لَكَ الْحَمْدُ كَمَا يَنْبَغِي لِجَلَالِ وَجْهِكَ , وَلِعَظِيمِ سُلْطَانِكَ.","c":3,"s":"رواه ابن ماجه","f":"weak","w":"إسناده ضعيف — ضعّفه الألباني (ضعيف ابن ماجه)"},{"t":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ ، عَلَيْكَ تَوَكَّلْتُ ، وَأَنْتَ رَبُّ الْعَرْشِ الْعَظِيمِ , مَا شَاءَ اللَّهُ كَانَ ، وَمَا لَمْ يَشَأْ لَمْ يَكُنْ ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ , أَعْلَمُ أَنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ، وَأَنَّ اللَّهَ قَدْ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا , اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي ، وَمِنْ شَرِّ كُلِّ دَابَّةٍ أَنْتَ آخِذٌ بِنَاصِيَتِهَا ، إِنَّ رَبِّي عَلَى صِرَاطٍ مُسْتَقِيمٍ.","c":1,"v":"ذِكْرٌ طَيِّبٌ.","s":"رواه ابن السني","f":"weak","w":"إسناده ضعيف جدًا — لا يثبت عن النبي ﷺ"},{"t":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ.","c":100,"v":"حُطَّتْ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ. لَمْ يَأْتِ أَحَدٌ يَوْمَ الْقِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلَّا أَحَدٌ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَيْهِ.","s":"رواه مسلم، وأصله متفق عليه"},{"t":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى نَبِيِّنَا مُحَمَّدٍ.","c":10,"v":"مَنْ صَلَّى عَلَيَّ حِينَ يُصْبِحُ وَحِينَ يُمْسِي أَدْرَكَتْهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ.","s":"رواه الطبراني","f":"weak","w":"الفضل المذكور («أدركته شفاعتي») إسناده ضعيف على الأرجح. والصلاة على النبي ﷺ مشروعة في كل وقت: «من صلى علي صلاة صلى الله عليه بها عشرًا» — رواه مسلم"},{"t":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.","c":100,"v":"كَانَتْ لَهُ عَدْلَ عَشْرِ رِقَابٍ، وَكُتِبَتْ لَهُ مِئَةُ حَسَنَةٍ، وَمُحِيَتْ عَنْهُ مِئَةُ سَيِّئَةٍ، وَكَانَتْ لَهُ حِرْزًا مِنَ الشَّيْطَانِ.","s":"متفق عليه من حديث أبي هريرة"}],"after":[{"t":"أَسْتَغْفِرُ اللَّهَ، أَسْتَغْفِرُ اللَّهَ، أَسْتَغْفِرُ اللَّهَ.\nاللَّهُمَّ أَنْتَ السَّلَامُ ، وَمِنْكَ السَّلَامُ ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ .","c":1,"s":"رواه مسلم من حديث ثوبان"},{"t":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ.","c":1,"s":"متفق عليه من حديث المغيرة بن شعبة"},{"t":"لَا إِلَهَ إِلَّا اللَّهُ، وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، لَا إِلَهَ إِلَّا اللَّهُ، وَلَا نَعْبُدُ إِلَّا إِيَّاهُ، لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ، لَا إِلَهَ إِلَّا اللَّهُ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ.","c":1,"s":"رواه مسلم من حديث عبد الله بن الزبير"},{"t":"سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ ، وَاللَّهُ أَكْبَرُ.","c":33,"s":"رواه مسلم من حديث أبي هريرة"},{"t":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.","c":1,"s":"رواه مسلم من حديث أبي هريرة — تمام المائة"},{"t":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\nقُلْ هُوَ اللَّهُ أَحَدٌ، اللَّهُ الصَّمَدُ، لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ.\nبِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ، مِن شَرِّ مَا خَلَقَ، وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ، وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ، وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ.\nبِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ النَّاسِ، مَلِكِ النَّاسِ، إِلَٰهِ النَّاسِ، مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ، الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ، مِنَ الْجِنَّةِ وَالنَّاسِ.","c":3,"v":"ثَلَاثَ مَرَّاتٍ بَعْدَ صَلَاتَيِ الْفَجْرِ وَالْمَغْرِبِ. وَمَرَّةً بَعْدَ الصَّلَوَاتِ الْأُخْرَى.","s":"رواه أبو داود والترمذي والنسائي من حديث عقبة بن عامر، وصححه الألباني (مرة دبر كل صلاة)؛ والتثليث بعد الفجر والمغرب لحديث أذكار الصباح والمساء"},{"t":"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ\nاللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ. [آيَةُ الْكُرْسِيِّ - الْبَقَرَةُ 255]","c":1,"s":"رواه النسائي في الكبرى من حديث أبي أمامة، وصححه الألباني"},{"t":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.","c":10,"v":"عَشْرَ مَرَّاتٍ بَعْدَ الْمَغْرِبِ وَالصُّـبْحِ.","s":"رواه الترمذي وأحمد، وصححه الألباني لغيره (صحيح الترغيب 477)"},{"t":"اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا ، وَعَمَلًا مُتَقَبَّلًا.","c":1,"v":"بَعْدَ السَّلَامِ مِنْ صَلَاةِ الْفَجْرِ.","s":"رواه ابن ماجه وأحمد من حديث أم سلمة، وصححه الألباني"},{"t":"اللَّهُمَّ أَجِرْنِي مِنَ النَّارِ.","c":7,"v":"بَعْدَ صَلَاةِ الصُّبْحِ وَالْمَغْرِبِ.","s":"رواه أبو داود","f":"weak","w":"إسناده ضعيف — ضعّفه الألباني (ضعيف أبي داود)"},{"t":"اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ.","c":1,"s":"رواه أبو داود والنسائي من حديث معاذ بن جبل، وصححه الألباني"}],"masjid":[{"t":"يَقُولُ مِثْلَ مَا يَقُولُ الْمُؤَذِّنُ إِلَّا فِي \"حَيَّ عَلَى الصَّلَاةِ وَحَيَّ عَلَى الْفَلَاحِ\" فَيَقُولُ: \"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ\".","c":1,"h":"مَا يُقَالُ عِنْدَ سَمَاعِ الْأَذَانِ","s":"متفق عليه، والاستثناء عند «حي على الصلاة» و«حي على الفلاح» عند مسلم"},{"t":"عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: \"مَنْ قَالَ حِينَ يَسْمَعُ الْمُؤَذِّنَ : أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ ، رَضِيتُ بِاللَّهِ رَبًّا ، وَبِمُحَمَّدٍ رَسُولًا ، وَبِالْإِسْلَامِ دِينًا ، غُفِرَ لَهُ ذَنْبُهُ\". رَوَاهُ مُسْلِمٌ .","c":1,"s":"رواه مسلم"},{"t":"عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ : \"إِذَا سَمِعْتُمُ النِّدَاءَ فَقُولُوا مِثْلَ مَا يَقُولُ ، ثُمَّ صَلُّوا عَلَيَّ ، فَإِنَّهُ مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا ، ثُمَّ سَلُوا اللَّهَ لِيَ الْوَسِيلَةَ ، فَإِنَّهَا مَنْزِلَةٌ فِي الْجَنَّةِ لَا تَنْبَغِي إِلَّا لِعَبْدٍ مِنْ عِبَادِ اللَّهِ وَأَرْجُو أَنْ أَكُونَ أَنَا هُوَ ، فَمَنْ سَأَلَ لِيَ الْوَسِيلَةَ حَلَّتْ لَهُ الشَّفَاعَةُ\". رَوَاهُ مُسْلِمٌ .","c":1,"s":"رواه مسلم"},{"t":"عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ : \"مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ : اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ ، وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ ، حَلَّتْ لَهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ\" .رَوَاهُ الْبُخَارِيُّ .","c":1,"s":"رواه البخاري"},{"t":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى سَيِّدِنَا مُحَمَّدٍ.\nاللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ.","c":1,"h":"مَا يُقَالُ بَعْدَ سَمَاعِ الْأَذَانِ","s":"الصلاة على النبي ﷺ بعد الأذان عند مسلم، والدعاء لفظ البخاري","x":"حُذفت زيادة «إنك لا تخلف الميعاد» لأنها لم تثبت (زيادة شاذة عند البيهقي)"},{"t":"مَا بَيْنَ الْأَذَانِ وَالْإِقَامَةِ فَالدُّعَاءُ عِنْدَئِذٍ مُرَغَّبٌ فِيهِ وَمُسْتَحَبٌّ.\nقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: \"الدُّعَاءُ لَا يُرَدُّ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ\".\nقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: \"إِنَّ الدُّعَاءَ لَا يُرَدُّ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ فَادْعُوا\".","c":1,"h":"مَا يُقَالُ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ","s":"رواه أبو داود والترمذي وأحمد من حديث أنس، وصححه الألباني"},{"t":"اللَّهُ أَكْبَرُ ، اللَّهُ أَكْبَرُ\nاللَّهُ أَكْبَرُ ، اللَّهُ أَكْبَرُ\nأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ\nأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ\nأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ\nأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ\nحَيَّ عَلَى الصَّلَاةِ\nحَيَّ عَلَى الصَّلَاةِ\nحَيَّ عَلَى الْفَلَاحِ\nحَيَّ عَلَى الْفَلَاحِ\nاللَّهُ أَكْبَرُ ، اللَّهُ أَكْبَرُ\nلَا إِلَهَ إِلَّا اللَّهُ","c":1,"h":"نَصُّ صِيغَةِ الْأَذَانِ","s":"رواه أبو داود من حديث عبد الله بن زيد، وصححه الألباني","f":"ref","w":"نص الأذان للاطلاع — لا يُعرض ذكرًا"},{"t":"اللَّهُ أَكْبَرُ ، اللَّهُ أَكْبَرُ\nاللَّهُ أَكْبَرُ ، اللَّهُ أَكْبَرُ\nأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ\nأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ\nأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ\nأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ\nحَيَّ عَلَى الصَّلَاةِ\nحَيَّ عَلَى الصَّلَاةِ\nحَيَّ عَلَى الْفَلَاحِ\nحَيَّ عَلَى الْفَلَاحِ\nالصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ\nالصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ\nاللَّهُ أَكْبَرُ ، اللَّهُ أَكْبَرُ\nلَا إِلَهَ إِلَّا اللَّهُ","c":1,"h":"نَصُّ صِيغَةِ أَذَانِ الْفَجْرِ","s":"رواه أبو داود والنسائي، وصححه الألباني","f":"ref","w":"نص أذان الفجر للاطلاع — لا يُعرض ذكرًا"},{"t":"اللَّهُ أَكْبَرُ ، اللَّهُ أَكْبَرُ\nأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ\nأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ\nحَيَّ عَلَى الصَّلَاةِ\nحَيَّ عَلَى الْفَلَاحِ\nقَدْ قَامَتِ الصَّلَاةُ\nقَدْ قَامَتِ الصَّلَاةُ\nاللَّهُ أَكْبَرُ ، اللَّهُ أَكْبَرُ\nلَا إِلَهَ إِلَّا اللَّهُ","c":1,"h":"نَصُّ صِيغَةِ الْإِقَامَةِ","s":"متفق عليه: «أُمر بلال أن يشفع الأذان ويوتر الإقامة»","f":"ref","w":"نص الإقامة للاطلاع — لا يُعرض ذكرًا"},{"t":"اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا ، وَفِي لِسَانِي نُورًا، وَاجْعَلْ فِي سَمْعِي نُورًا، وَاجْعَلْ فِي بَصَرِي نُورًا، وَاجْعَلْ مِنْ خَلْفِي نُورًا، وَمِنْ أَمَامِي نُورًا، وَاجْعَلْ مِنْ فَوْقِي نُورًا ، وَمِنْ تَحْتِي نُورًا .اللَّهُمَّ أَعْطِنِي نُورًا.","c":1,"h":"دُعَاءُ الذَّهَابِ إِلَى الْمَسْجِدِ","s":"متفق عليه من حديث ابن عباس"},{"t":"يَبْدَأُ بِرِجْلِهِ الْيُمْنَى، وَيَقُولُ:\nأَعُوذُ بِاللَّهِ الْعَظِيمِ وَبِوَجْهِهِ الْكَرِيمِ وَسُلْطَانِهِ الْقَدِيمِ مِنَ الشَّيْطَانِ الرَّجِيمِ، بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ.","c":1,"h":"دُعَاءُ دُخُولِ الْمَسْجِدِ","s":"رواه أبو داود (الاستعاذة) وابن السني (التسمية) ومسلم («اللهم افتح لي أبواب رحمتك»)، وصححه الألباني"},{"t":"يَبْدَأُ بِرِجْلِهِ الْيُسْرَى، وَيَقُولُ:\nبِسْمِ اللَّهِ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ، اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ.","c":1,"h":"دُعَاءُ الْخُرُوجِ مِنَ الْمَسْجِدِ","s":"رواه مسلم («اللهم إني أسألك من فضلك») وابن ماجه («اللهم اعصمني من الشيطان الرجيم»)، وصححه الألباني"}]};
const IB_CATS = [{"k":"tasabeeh","ar":"تسابيح","en":"Tasbeeh","items":[{"t":"سُبْحَانَ اللَّهِ","c":100,"v":"يُكْتَبُ لَهُ أَلْفُ حَسَنَةٍ أَوْ يُحَطُّ عَنْهُ أَلْفُ خَطِيئَةٍ.","s":"رواه مسلم من حديث سعد بن أبي وقاص"},{"t":"اللَّهُ أَكْبَرُ","c":100,"v":"مَنْ قَالَ اللَّهُ أَكْبَرُ كُتِبَتْ لَهُ عِشْرُونَ حَسَنَةً وَحُطَّتْ عَنْهُ عِشْرُونَ سَيِّئَةً. اللَّهُ أَكْبَرُ مِنْ كُلِّ شَيْءٍ.","s":"رواه أحمد والنسائي في الكبرى والحاكم، وصححه الألباني (صحيح الجامع 1718)"},{"t":"أَسْتَغْفِرُ اللَّهَ","c":100,"v":"لِفِعْلِ الرَّسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.","s":"رواه مسلم: «إني لأستغفر الله في اليوم مائة مرة»"},{"t":"لَا إِلَهَ إِلَّا اللَّهُ","c":100,"v":"أَفْضَلُ الذِّكْرِ لَا إِلَهَ إِلَّا اللَّهُ.","s":"رواه الترمذي وابن ماجه من حديث جابر، وحسّنه الألباني"},{"t":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","c":100,"v":"حُطَّتْ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ. لَمْ يَأْتِ أَحَدٌ يَوْمَ الْقِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلَّا أَحَدٌ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَيْهِ.","s":"متفق عليه، و«لم يأت أحد يوم القيامة بأفضل…» عند مسلم"},{"t":"الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ","c":100,"v":"تَمْلَأُ مِيزَانَ الْعَبْدِ بِالْحَسَنَاتِ.","s":"رواه مسلم: «والحمد لله تملأ الميزان»"},{"t":"سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ","c":100,"v":"تَمْلَآنِ مَا بَيْنَ السَّمَاوَاتِ وَالْأَرْضِ.","s":"رواه مسلم من حديث أبي مالك الأشعري"},{"t":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","c":100,"v":"كَنْزٌ مِنْ كُنُوزِ الْجَنَّةِ (أَيُّ عَدَدٍ).","s":"متفق عليه من حديث أبي موسى"},{"t":"سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ","c":100,"v":"غُرِسَتْ لَهُ نَخْلَةٌ فِي الْجَنَّةِ (أَيُّ عَدَدٍ).","s":"رواه الترمذي من حديث جابر، وصححه الألباني"},{"t":"اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى سَيِّدِنَا مُحَمَّدٍ","c":100,"v":"«من صلى علي صلاة صلى الله عليه بها عشرًا» — رواه مسلم","s":"الصلاة على النبي ﷺ — رواه مسلم"},{"t":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ ، سُبْحَانَ اللَّهِ الْعَظِيمِ","c":100,"v":"ثَقِيلَتَانِ فِي الْمِيزَانِ حَبِيبَتَانِ إِلَى الرَّحْمَنِ (أَيُّ عَدَدٍ).","s":"متفق عليه من حديث أبي هريرة"},{"t":"الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ.","c":100,"v":"قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏\"‏لَقَدْ رَأَيْتُ اثْنَيْ عَشَرَ مَلَكًا يَبْتَدِرُونَهَا، أَيُّهُمْ يَرْفَعُهَا\"‏.","s":"رواه مسلم من حديث أنس"},{"t":"سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ","c":100,"v":"أَنَّهُنَّ أَحَبُّ الْكَلَامِ إِلَى اللَّهِ، وَمُكَفِّرَاتٌ لِلذُّنُوبِ، وَغَرْسُ الْجَنَّةِ، وَجُنَّةٌ لِقَائِلِهِنَّ مِنَ النَّارِ، وَأَحَبُّ إِلَى النَّبِيِّ عَلَيْهِ السَّلَامُ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ، وَالْبَاقِيَاتُ الصَّالِحَاتُ.","s":"«أحب الكلام إلى الله» رواه مسلم، وبقية الفضائل عند الترمذي وابن ماجه والنسائي بأسانيد حسنة"},{"t":"اللَّهُ أَكْبَرُ كَبِيرًا ، وَالْحَمْدُ لِلَّهِ كَثِيرًا ، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا.","c":100,"v":"قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ \"عَجِبْتُ لَهَا ، فُتِحَتْ لَهَا أَبْوَابُ السَّمَاءِ\".","s":"رواه مسلم من حديث ابن عمر"},{"t":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.","c":100,"v":"كَانَتْ لَهُ عَدْلَ عَشْرِ رِقَابٍ، وَكُتِبَتْ لَهُ مِئَةُ حَسَنَةٍ، وَمُحِيَتْ عَنْهُ مِئَةُ سَيِّئَةٍ، وَكَانَتْ لَهُ حِرْزًا مِنَ الشَّيْطَانِ.","s":"متفق عليه من حديث أبي هريرة"},{"t":"سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.","c":100,"v":"الْبَاقِيَاتُ الصَّالِحَاتُ وَكَنْزٌ مِنْ كُنُوزِ الْجَنَّةِ.","s":"«كنز من كنوز الجنة» متفق عليه، و«الباقيات الصالحات» عند أحمد والنسائي في الكبرى"},{"t":"سُبْحَانَ اللَّهِ ، وَالْحَمْدُ لِلَّهِ ، وَلَا إِلَهَ إِلَّا اللَّهُ ، وَاللَّهُ أَكْبَرُ ، اللَّهُمَّ اغْفِرْ لِي ، اللَّهُمَّ ارْحَمْنِي ، اللَّهُمَّ ارْزُقْنِي.","c":100,"v":"خَيْرُ الدُّنْيَا وَالْآخِرَةِ","s":"رواه مسلم من حديث سعد بن أبي وقاص وطارق بن أشيم"},{"t":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ , وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ , اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ.","c":100,"v":"فِي كُلِّ مَرَّةٍ تُحَطُّ عَنْهُ عَشْرُ خَطَايَا وَيُرْفَعُ لَهُ عَشْرُ دَرَجَاتٍ وَيُصَلِّي اللَّهُ عَلَيْهِ عَشْرًا وَتُعْرَضُ عَلَى الرَّسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ (أَيُّ عَدَدٍ).","s":"الصلاة الإبراهيمية متفق عليها، والفضل رواه النسائي من حديث أنس، وصححه الألباني"}]},{"k":"salah","ar":"أذكار الصلاة","en":"In the prayer","items":[{"t":"اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْنِي مِنْ خَطَايَايَ، بِالثَّلْجِ وَالْمَاءِ وَالْبَرَدِ.\nسُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرُكَ.\nالْحَمْدُ لِلَّهِ حَمْداً كَثِيراً طَيِّباً مُبَارَكاً فِيهِ.\nاللَّهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا. أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ: مِنْ نَفْخِهِ، وَنَفْثِهِ، وَهَمْزِهِ.\nاللَّهُمَّ رَبَّ جَبْرَائِيلَ، وَمِيكَائِيلَ، وَإِسْرَافِيلَ، فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ، اِهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُّسْتَقِيمٍ.\nوَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالْأَرْضَ حَنِيفًا وَّمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلَاتِي، وَنُسُكِي، وَمَحْيَايَ، وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ، اللَّهُمَّ أَنْتَ الْمَلِكُ لَا إِلَهَ إِلَّا أَنْتَ، أَنْتَ رَبِّي وَأَنَا عَبْدُكَ، ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ. وَاهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا، لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ، لَبَّيْكَ وَسَعْدَيْكَ، وَالْخَيْرُ كُلُّهُ بِيَدَيْكَ، وَالشَّرُّ لَيْسَ إِلَيْكَ، أَنَا بِكَ وَإِلَيْكَ، تَبَارَكْتَ وَتَعَالَيْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ.","c":1,"h":"أَدْعِيَةُ اسْتِفْتَاحِ الصَّلَاةِ","s":"متفق عليه، وبقية صيغ الاستفتاح عند مسلم وأهل السنن بأسانيد صحيحة"},{"t":"سُبْحَانَ رَبِّيَ الْعَظِيمِ. ثَلَاثَ مَرَّاتٍ أَوْ أَكْثَرَ.\nسُبْحَانَ رَبِّيَ الْعَظِيمِ وَبِحَمْدِهِ. ثَلَاثَ مَرَّاتٍ.\nسُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي.\nسُبُّوحٌ، قُدُّوسٌ، رَبُّ الْمَلَائِكَةِ وَالرُّوحِ.\nسُبْحَانَ ذِي الْجَبَرُوتِ، وَالْمَلَكُوتِ، وَالْكِبْرِيَاءِ، وَالْعَظَمَةِ.\nاللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي وَبَصَرِي، وَمُخِّي وَعَظْمِي وَعَصَبِي.","c":1,"h":"أَدْعِيَةُ الرُّكُوعِ","s":"رواه مسلم وأهل السنن بأسانيد صحيحة"},{"t":"سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ.\nرَبَّنَا وَلَكَ الْحَمْدُ، حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ.\nاللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي، و بَصَرِي، وَمُخِّي، وَعَظْمِي، وَعَصَبِي، وَمَا اسْتَقَلَّتْ بِهِ قَدَمِي لِلَّهِ رَبِّ الْعَالَمِينَ.\nاللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْأَرْضِ، وَمَا بَيْنَهُمَا، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ، أَهْلَ الثَّنَاءِ وَالْمَجْدِ، أَحَقُّ مَا قَالَ الْعَبْدُ، وَكُلُّنَا لَكَ عَبْدٌ، اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ.\nاللَّهُمَّ لَكَ الْحَمْدُ مِلْءَ السَّمَاءِ، وَمِلْءَ الْأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ، اللَّهُمَّ طَهِّرْنِي بِالثَّلْجِ وَالْبَرَدِ، وَالْمَاءِ الْبَارِدِ، اللَّهُمَّ طَهِّرْنِي مِنَ الذُّنُوبِ وَالْخَطَايَا، كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الْوَسَخِ.","c":1,"h":"أَدْعِيَةُ الرَّفْعِ مِنَ الرُّكُوعِ","s":"رواه البخاري ومسلم"},{"t":"سُبْحَانَ رَبِّيَ الْأَعْلَى. ثَلَاثَ مَرَّاتٍ أَوْ أَكْثَرَ.\nسُبْحَانَ رَبِّيَ الْأَعْلَى وَبِحَمْدِهِ. ثَلَاثَ مَرَّاتٍ.\nسُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ.\nسُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي.\nسُبْحَانَ ذِي الْجَبْرُوتِ وَالْمَلَكُوتِ وَالْكِبْرِيَاءِ وَالْعَظَمَةِ.\nاللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَتَهُ وَسِرَّهُ.\nاللَّهُمَّ لَكَ سَجَدْتُ وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ، وَصَوَّرَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ.\nرَبِّ أَعْطِ نَفْسِي تَقْوَاهَا زَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا أَنْتَ وَلِيُّهَا وَمَوْلَاهَا.\nاللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا وَاجْعَلْ فِي سَمْعِي نُورًا وَاجْعَلْ فِي بَصَرِي نُورًا وَاجْعَلْ مِنْ تَحْتِي نُورًا وَاجْعَلْ مِنْ فَوْقِي نُورًا وَعَنْ يَمِينِي نُورًا وَعَنْ يَسَارِي نُورًا وَاجْعَلْ أَمَامِي نُورًا وَاجْعَلْ خَلْفِي نُورًا وَأَعْظِمْ لِي نُورًا.","c":1,"h":"أَدْعِيَةُ السُّجُودِ","v":"بَعْدَ أَنْ يَخْتَارَ أَحَدَ أَدْعِيَةِ السُّجُودِ ، يُسَنُّ لَهُ أَنْ يَدْعُوَ بِمَا شَاءَ ،لِأَنَّ \"أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ، فَأَكْثِرُوا الدُّعَاءَ\".","s":"رواه مسلم وأهل السنن بأسانيد صحيحة"},{"t":"رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي.\nاللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَاجْبُرْنِي، وَعَافِنِي، وَارْزُقْنِي، وَارْفَعْنِي.","c":1,"h":"أَدْعِيَةُ الْجُلُوسِ بَيْنَ السَّجْدَتَيْنِ","v":"كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُطِيلُ هَذَا الرُّكْنَ بِقَدْرِ السُّجُودِ.","s":"رواه أبو داود والترمذي وابن ماجه، وصححه الألباني"},{"t":"سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ، بِحَوْلِهِ وَقُوَّتِهِ، فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ.\nاللَّهُمَّ اكْتُبْ لِي بِهَا عِنْدَكَ أَجْرًا، وَضَعْ عَنِّي بِهَا وِزْرًا، وَاجْعَلْهَا لِي عِنْدِكَ ذُخْراً، وَتَقَبَّلْهَا مِنِّي كَمَا تَقَبَّلْتَهَا مِنْ عَبْدِكَ دَاوُدَ.","c":1,"h":"دُعَاءُ سُجُودِ التِّلَاوَةِ","s":"رواه الترمذي وأحمد، وصححه الألباني"},{"t":"التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ.","c":1,"h":"التَّشَهُّدُ الْأَوَّلُ","v":"وَرَدَتْ صِيَغٌ أُخْرَى لِلتَّشَهُّدِ قَرِيبَةٌ مِنْ هَذَا.","s":"متفق عليه من حديث ابن مسعود"},{"t":"التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ. اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ.","c":1,"h":"التَّشَهُّدُ الْأَخِيرُ","s":"متفق عليه"},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ جَهَنَّمَ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ. وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ. وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ.\nاللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْماً كَثِيراً ، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ. فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ.\nاللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ. وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ. وَمَا أَسْرَفْتُ. وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي. أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ. لَا إِلَهَ إِلَّا أَنْتَ.\nرَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ يَا اللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ، أَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ.\nاللَّهُمَّ حَاسِبْنِي حِسَابًا يَسِيراً.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، الْمَنَّانُ، يَا بَدِيعَ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّومُ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ.\nاللَّهُمَّ بِعِلْمِكَ الْغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْغِنَى وَالْفَقْرِ، وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَالشَّوْقَ إِلَى لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ، وَلَا فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَّا بِزِينَةِ الْإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ.","c":1,"h":"أَدْعِيَةٌ بَعْدَ التَّشَهُّدِ الْأَخِيرِ وَقَبْلَ السَّلَامِ","s":"أدعية من الصحيحين والسنن بأسانيد صحيحة"},{"t":"اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ وَأَعُوذُ بِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ لَا أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ.\nاللَّهُمَّ إِيَّاكَ نَعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ، وَإِلَيْكَ نَسْعَى وَنَحْفِدُ، نَرْجُو رَحْمَتَكَ، وَنَخْشَى عَذَابَكَ، إِنَّ عَذَابَكَ بِالْكَافِرِينَ مُلْحِقٌ، اللَّهُمَّ إِنَّا نَسْتَعِينُكَ، وَنَسْتَغْفِرُكَ، وَنُثْنِي عَلَيْكَ الْخَيْرَ، وَلَا نَكْفُرُكَ، وَنُؤْمِنُ بِكَ وَنَخْضَعُ لَكَ، وَنَخْلَعُ مَنْ يَكْفُرُكَ.\nاللَّهُمَّ تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ. وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلَّمَ.","c":1,"h":"دُعَاءُ الْقُنُوتِ","v":"دُعَاءُ الْقُنُوتِ يَكُونُ فِي الرَّكْعَةِ الْأَخِيرَةِ مِنْ صَلَاةِ الْوِتْرِ بَعْدَ الرُّكُوعِ ، وَإِذَا جَعَلَهُ قَبْلَ الرُّكُوعِ فَلَا بَأْسَ ، إِلَّا أَنَّهُ بَعْدَ الرُّكُوعِ أَفْضَلُ ، وَيَرْفَعُ يَدَيْهِ إِلَى صَدْرِهِ وَلَا يَرْفَعُهَا كَثِيرًا . الْقُنُوتُ عِنْدَ النَّوَازِلِ سُنَّةٌ فِي جَمِيعِ الصَّلَوَاتِ الْخَمْسِ وَهُوَ فِي صَلَاةِ الْمَغْرِبِ وَالْفَجْرِ آكَدُ.","s":"رواه أبو داود والترمذي والنسائي من حديث الحسن بن علي، وصححه الألباني"},{"t":"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ وَأَصْلِحِ اللَّهُمَّ أَحْوَالَنَا فِي الْأُمُورِ كُلِّهَا وَبَلِّغْنَا بِمَا يُرْضِيكَ آمَالَنَا وَاخْتِمِ اللَّهُمَّ بِالصَّالِحَاتِ أَعْمَالَنَا وَبِالسَّعَادَةِ آجَالَنَا وَتَوَفَّنَا يَا رَبِّ وَأَنْتَ رَاضٍ عَنَّا.\nاللَّهُمَّ اجْعَلْ جَمْعَنَا هَذَا جَمْعًا مُبَارَكًا مَرْحُومًا وَتَفَرُّقَنَا مِنْ كُلِّ شَرٍّ مَعْصُومًا.\nرَبَّنَا لَا تَدَعْ لَنَا ذَنْبًا إِلَّا غَفَرْتَهُ وَلَا هَمًّا إِلَّا فَرَّجْتَهُ وَلَا مَرِيضًا إِلَّا شَفَيْتَهُ وَلَا مَيِّتًا إِلَّا رَحِمْتَهُ وَلَا طَالِبًا أَمْرًا مِنْ أُمُورِ الْخَيْرِ إِلَّا سَهَّلْتَهُ لَهُ وَيَسَّرْتَهُ.\nاللَّهُمَّ وَحِّدْ كَلِمَةَ الْمُسْلِمِينَ وَاجْمَعْ شَمْلَهُمْ وَاجْعَلْهُمْ يَدًا وَاحِدَةً عَلَى مَنْ سِوَاهُمْ وَانْصُرِ اللَّهُمَّ الْمُسْلِمِينَ وَاخْذُلِ الْكَفَرَةَ الْمُشْرِكِينَ أَعْدَاءَكَ أَعْدَاءَ الدِّينِ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ لِوُلَاةِ أُمُورِنَا الصَّلَاحَ وَالسَّدَادَ.\nاللَّهُمَّ كُنْ لَهُمْ عَوْنًا وَخُذْ بِأَيْدِيهِمْ إِلَى الْحَقِّ وَالصَّوَابِ وَالسَّدَادِ وَالرَّشَادِ وَوَفِّقْهُمْ لِلْعَمَلِ لِمَا فِيهِ رِضَاكَ وَمَا فِيهِ صَالِحُ الْعِبَادِ وَالْبِلَادِ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ لِبَلَدِنَا هَذَا اللَّهُمَّ اجْعَلْهُ بَلَدًا آمِنًا وَارْزُقْهُ مِنْ كُلِّ الْخَيْرَاتِ وَجَنِّبْهُ الْفِتَنَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَأَلِّفِ اللَّهُمَّ مَا بَيْنَ قُلُوبِنَا وَبَيْنَ قُلُوبِ أَبْنَاءِ هَذَا الْوَطَنِ وَاجْعَلْهُمُ اللَّهُمَّ يَا رَبَّنَا بِاسْمِكَ مُتَحَابِّينَ وَعَلَى\nنُصْرَةِ دِينِكَ مُتَعَاوِنِينَ.\nاللَّهُمَّ إِنَّا نَسْتَعِيذُ بِكَ مِنْ شَرِّ مَا خَلَقْتَ وَمِنْ كُلِّ عَيْنِ حَاسِدٍ و نَسْأَلُكَ اللَّهُمَّ التَّوْفِيقَ وَالسَّدَادَ وَالْهِدَايَةَ وَالرَّشَادَ وَحُسْنَ الْعُقْبَى وَحُسْنَ الْمِيعَادِ.\nاللَّهُمَّ أَسْبِغْ عَلَيْنَا نِعْمَتَكَ وَعَلَى جَمِيعِ الْمُسْلِمِينَ وَامْلَأِ اللَّهُمَّ قُلُوبَنَا بِالْإِيمَانِ وَالْقَنَاعَةِ وَأَلْزِمْ جَوَارِحَنَا الْعِبَادَةَ وَالطَّاعَةَ وَاغْفِرِ اللَّهُمَّ لَنَا وَلِوَالِدَيْنَا وَلِإِخْوَانِنَا وَأَشْيَاخِنَا وَلِجَمِيعِ مَنْ سَبَقَنَا بِالْإِيمَانِ وَآتِنَا مِنْ لَدُنْكَ رَحْمَةً\nوَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا وَآتِنَا رَبَّنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ.\nسُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ وَسَلَامٌ عَلَى الْمُرْسَلِينَ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.","c":1,"h":"دُعَاءُ خُطْبَةِ الْجُمُعَةِ","s":"آيات من القرآن الكريم وأدعية عامة","f":"gen","w":"ليس دعاءً مأثورًا عن النبي ﷺ بهذا اللفظ مخصوصًا بالخطبة — أدعية عامة يختارها الخطيب"}]},{"k":"sleep","ar":"أذكار النوم","en":"Before sleep","items":[{"t":"بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي ، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا ، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ.","c":1,"s":"متفق عليه من حديث أبي هريرة"},{"t":"اللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا لَكَ مَمَاتُهَا وَمَحْيَاهَا ، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا ، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا . اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ.","c":1,"s":"رواه مسلم من حديث ابن عمر"},{"t":"اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ.","c":3,"s":"رواه أبو داود من حديث حفصة، وصححه الألباني"},{"t":"بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا.","c":1,"s":"رواه البخاري من حديث حذيفة"},{"t":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ.","c":1,"s":"رواه مسلم من حديث أنس"},{"t":"اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ .","c":1,"s":"رواه أبو داود والترمذي، وصححه الألباني"},{"t":"اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ.","c":1,"s":"متفق عليه من حديث البراء بن عازب"},{"t":"سُبْحَانَ اللَّهِ.","c":33,"s":"متفق عليه من حديث علي"},{"t":"الْحَمْدُ لِلَّهِ.","c":33,"s":"متفق عليه من حديث علي"},{"t":"اللَّهُ أَكْبَرُ.","c":34,"s":"متفق عليه من حديث علي"},{"t":"يَجْمَعُ كَفَّيْهِ ثُمَّ يَنْفُثُ فِيهِمَا وَالْقِرَاءَةُ فِيهِمَا: {قُلْ هُوَ اللَّهُ أَحَدٌ} وَ{قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} وَ{قُلْ أَعُوذُ بِرَبِّ النَّاسِ} وَمَسْحُ مَا اسْتَطَاعَ مِنَ الْجَسَدِ يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ وَمَا أَقْبَلَ مِنْ جَسَدِهِ.","c":3,"s":"رواه البخاري من حديث عائشة"},{"t":"سُورَةُ الْبَقَرَةِ: أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ\nآمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ. لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ.\n[الْبَقَرَةُ 285 - 286]","c":1,"v":"مَنْ قَرَأَ آيَتَيْنِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ.","s":"متفق عليه من حديث أبي مسعود الأنصاري"},{"t":"آيَةُ الْكُرْسِيِّ: أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ\nاللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ. [الْبَقَرَةُ 255]","c":1,"v":"أُجِيرَ مِنَ الْجِنِّ حَتَّى يُصْبِحَ.","s":"رواه البخاري من حديث أبي هريرة"},{"t":"عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ، قَالَ: شَكَا خَالِدُ بْنُ الْوَلِيدِ رَضِيَ اللَّهُ عَنْهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! مَا أَنَامُ اللَّيْلَ مِنَ الْأَرَقِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: \"إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَقُلْ: اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَمَا أَظَلَّتْ، وَرَبَّ الْأَرَضِينَ وَمَا أَقَلَّتْ، وَرَبَّ الشَّيَاطِينِ وَمَا أَضَلَّتْ، كُنْ لِي جَارًا مِنْ خَلْقِكَ كُلِّهِمْ جَمِيعًا أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ أَنْ يَبْغِيَ عَلَيَّ، عَزَّ جَارُكَ، وَجَلَّ ثَنَاؤُكَ وَلَا إِلَهَ غَيْرُكَ، وَلَا إِلَهَ إِلَّا أَنْتَ\"\nعَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعَلِّمُهُمْ مِنَ الْفَزَعِ كَلِمَاتٍ: \"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ غَضَبِهِ وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ\"","c":1,"h":"أَذْكَارُ مَنْ قَلِقَ فِي فِرَاشِهِ وَلَمْ يَنَمْ","s":"الترمذي (حديث بريدة) — أبو داود والترمذي (حديث عمرو بن شعيب)","f":"weak","w":"حديث بريدة في أوله ضعيف جدًا — ضعّفه الألباني؛ أما «أعوذ بكلمات الله التامة من غضبه…» فحسن (أبو داود والترمذي)"},{"t":"عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: \"الرُّؤْيَا الصَّالِحَةُ\" وَفِي رِوَايَةٍ \"الرُّؤْيَا الْحَسَنَةُ مِنَ اللَّهِ، وَالْحُلْمُ مِنَ الشَّيْطَانِ، فَمَنْ رَأَى شَيْئًا يَكْرَهُهُ فَلْيَنْفُثْ عَنْ شِمَالِهِ ثَلَاثًا وَلْيَتَعَوَّذْ مِنَ الشَّيْطَانِ، فَإِنَّهَا لَا تَضُرُّهُ\".","c":1,"h":"أَذْكَارُ الْأَحْلَامِ","s":"متفق عليه من حديث أبي قتادة"}]},{"k":"wake","ar":"أذكار الاستيقاظ","en":"On waking","items":[{"t":"الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ.","c":1,"s":"رواه البخاري من حديث حذيفة"},{"t":"الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي وَرَدَّ عَلَيَّ رُوحِي وَأَذِنَ لِي بِذِكْرِهِ.","c":1,"s":"رواه الترمذي من حديث أبي هريرة، وحسّنه الألباني"},{"t":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ ، وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ. رَبِّ اغْفِرْ لِي.","c":1,"s":"رواه البخاري من حديث عبادة بن الصامت، و«رب اغفر لي» لفظ ابن ماجه"}]},{"k":"wudu","ar":"أذكار الوضوء","en":"Wudu","items":[{"t":"قَبْلَ الْوُضُوءِ: \"بِسْمِ اللَّهِ\".","c":1,"h":"الذِّكْرُ قَبْلَ الْوُضُوءِ","s":"رواه أبو داود وابن ماجه، وصححه الألباني"},{"t":"\"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ\".\n\"اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ\".\n\"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ\".","c":1,"h":"الذِّكْرُ بَعْدَ الْوُضُوءِ","s":"رواه مسلم، والترمذي («اللهم اجعلني من التوابين…»)، والنسائي في عمل اليوم والليلة («سبحانك اللهم وبحمدك…»)، وصححه الألباني"}]},{"k":"home","ar":"أذكار المنزل","en":"Home","items":[{"t":"بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى رَبِّنَا تَوَكَّلْنَا.","c":1,"h":"أَذْكَارُ الدُّخُولِ إِلَى الْمَنْزِلِ","s":"رواه أبو داود","f":"disp","w":"مختلف في ثبوته: حسّنه بعض العلماء وضعّفه الألباني. والثابت: التسمية عند دخول البيت والسلام على أهله (مسلم)"},{"t":"بِسْمِ اللَّهِ ، تَوَكَّلْتُ عَلَى اللَّهِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ ، أَوْ أَزِلَّ أَوْ أُزَلَّ ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ.","c":1,"h":"أَذْكَارُ الْخُرُوجِ مِنَ الْمَنْزِلِ","s":"رواه أبو داود والترمذي، وصححه الألباني"}]},{"k":"khala","ar":"أذكار الخلاء","en":"Restroom","items":[{"t":"(بِسْمِ اللَّهِ) اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبْثِ وَالْخَبَائِثِ.","c":1,"h":"الذِّكْرُ عِنْدَ الْخَلَاءِ","s":"متفق عليه، والتسمية عند الترمذي وسعيد بن منصور، وصححه الألباني"},{"t":"غُفْرَانَكَ.","c":1,"h":"الذِّكْرُ بَعْدَ الْخُرُوجِ مِنَ الْخَلَاءِ","s":"رواه أبو داود والترمذي وابن ماجه، وصححه الألباني"}]},{"k":"food","ar":"أذكار الطعام","en":"Food","items":[{"t":"بِسْمِ اللَّهِ.\nفَإِنْ نَسِيَ فِي أَوَّلِهِ، فَلْيَقُلْ:\nبِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ.","c":1,"h":"الذِّكْرُ عِنْدَ الطَّعَامِ وَالشَّرَابِ","s":"رواه أبو داود والترمذي من حديث عائشة، وصححه الألباني"},{"t":"اللَّهُمَّ بَارِكْ لَنَا فِيهِ, وَزِدْنَا مِنْهُ.","c":1,"h":"الذِّكْرُ عِنْدَ شُرْبِ اللَّبَنِ","s":"رواه أبو داود والترمذي من حديث ابن عباس، وحسّنه الألباني"},{"t":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا, وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ.\nالْحَمْدُ لِلَّهِ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ غَيْرَ مَكْفِيٍّ وَلَا مُوَدَّعٍ وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا.","c":1,"h":"الذِّكْرُ عِنْدَ الْفَرَاغِ مِنَ الطَّعَامِ وَالشَّرَابِ","v":"غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ.","s":"الأول رواه أبو داود والترمذي وابن ماجه، وحسّنه الألباني؛ والثاني رواه البخاري"},{"t":"أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ.","c":1,"h":"أَذْكَارُ الضَّيْفِ","s":"رواه أبو داود وأحمد من حديث أنس، وصححه الألباني"},{"t":"كَانَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَشْرَبُ فِي ثَلَاثَةِ أَنْفَاسٍ، إِذَا أَدْنَى الْإِنَاءَ إِلَى فَمِهِ سَمَّى اللَّهَ تَعَالَى, وَإِذَا أَخَّرَهُ حَمِدَ اللَّهَ تَعَالَى، يَفْعَلُ ذَلِكَ ثَلَاثَ مَرَّاتٍ.","c":1,"h":"هَدْيُ النَّبِيِّ فِي الشُّرْبِ","s":"الشرب في ثلاثة أنفاس متفق عليه، والتسمية والحمد عند الطبراني في الأوسط، وحسّنه الألباني (السلسلة الصحيحة 1277)"}]},{"k":"misc","ar":"أذكار متفرقة","en":"Various","items":[{"t":"الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا (الثَّوْبَ) وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ.","c":1,"h":"دُعَاءُ لُبْسِ الثَّوْبِ","s":"رواه أبو داود والترمذي، وحسّنه الألباني"},{"t":"اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ","c":1,"h":"دُعَاءُ لُبْسِ الثَّوْبِ الْجَدِيدِ","s":"رواه أبو داود والترمذي من حديث أبي سعيد، وصححه الألباني"},{"t":"لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ، وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ\nاللَّهُمَّ رَحْمَتَكَ أَرْجُو فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ وَأَصْلِحْ لِي شَأْنِي كُلَّهُ ، لَا إِلَهَ إِلَّا أَنْتَ\nلَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ\nاللَّهُ اللَّهُ رَبِّي لَا أُشْرِكُ بِهِ شَيْئًا","c":1,"h":"دُعَاءُ الْكَرْبِ","s":"الأول متفق عليه، والبقية عند أبي داود والترمذي بأسانيد صحيحة وحسنة"},{"t":"اللَّهُمَّ إِنِّي عَبْدُكَ ابْنُ عَبْدِكَ ابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ مَاضٍ فِيَّ حُكْمُكَ ، عَدْلٌ فِيَّ قَضَاؤُكَ أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي ، وَنُورَ صَدْرِي وَجَلَاءَ حُزْنِي وَذَهَابَ هَمِّي.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ وَالْبُخْلِ وَالْجُبْنِ ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ.","c":1,"h":"دُعَاءُ الْهَمِّ وَالْحَزَنِ","s":"رواه أحمد من حديث ابن مسعود، وصححه الألباني (السلسلة الصحيحة 199)"},{"t":"اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","c":1,"h":"دُعَاءُ قَضَاءِ الدَّيْنِ","s":"رواه الترمذي من حديث علي، وحسّنه الألباني"},{"t":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيهَا، وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيهَا وَشَرِّ مَا أُرْسِلَتْ بِهِ.","c":1,"h":"دُعَاءُ الرِّيحِ","s":"رواه مسلم من حديث عائشة"},{"t":"سُبْحَانَ اللَّهِ الَّذِي يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ وَالْمَلَائِكَةُ مِنْ خِيفَتِهِ","c":1,"h":"دُعَاءُ الرَّعْدِ","s":"رواه مالك في الموطأ والبخاري في الأدب المفرد موقوفًا على عبد الله بن الزبير، وصحح إسناده الألباني","f":"athar","w":"أثر عن الصحابي (موقوف)، وليس حديثًا مرفوعًا"},{"t":"السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ وَيَرْحَمُ اللَّهُ الْمُسْتَقْدِمِينَ مِنَّا وَالْمُسْتَأْخِرِينَ، أَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ.","c":1,"h":"دُعَاءُ زِيَارَةِ الْقُبُورِ","s":"رواه مسلم من حديث بريدة وعائشة"},{"t":"اللَّهُمَّ صَيِّبًا نَافِعًا","c":1,"h":"دُعَاءُ نُزُولِ الْمَطَرِ","s":"رواه البخاري من حديث عائشة"},{"t":"بِسْمِ اللَّهِ ، الْحَمْدُ لِلَّهِ ، سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ، الْحَمْدُ لِلَّهِ ، الْحَمْدُ لِلَّهِ ، الْحَمْدُ لِلَّهِ ، اللَّهُ أَكْبَرُ ، اللَّهُ أَكْبَرُ ، اللَّهُ أَكْبَرُ ، سُبْحَانَكَ اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي ، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ.","c":1,"h":"دُعَاءُ رُكُوبِ الدَّابَّةِ أَوْ مَا يَقُومُ مَقَامَهَا ( السَّيَّارَةِ أَوِ الْقِطَارِ أَوِ الطَّائِرَةِ أَوِ السَّفِينَةِ)","s":"رواه أبو داود والترمذي من حديث علي، وصححه الألباني"},{"t":"اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى ، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمَنْظَرِ وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ.\nوَإِذَا رَجَعَ قَالَهُنَّ وَزَادَ فِيهِنَّ ـ\" آيِبُونَ ،تَائِبُونَ، عَابِدُونَ ، لِرَبِّنَا حَامِدُونَ\"","c":1,"h":"دُعَاءُ السَّفَرِ","s":"رواه مسلم من حديث ابن عمر"},{"t":"أَسْتَوْدِعُكُمُ اللَّهَ الَّذِي لَا تَضِيعُ وَدَائِعُهُ","c":1,"h":"دُعَاءُ الْمُسَافِرِ لِلْمُقِيمِ","s":"رواه أحمد وابن ماجه من حديث أبي هريرة، وصححه الألباني"},{"t":"أَسْتَوْدِعُ اللَّهَ دِينَكَ وَأَمَانَتَكَ ، وَخَوَاتِيمَ عَمَلِكَ زَوَّدَكَ اللَّهُ التَّقْوَى، وَغَفَرَ ذَنْبَكَ، وَيَسَّرَ لَكَ الْخَيْرَ حَيْثُ مَا كُنْتَ","c":1,"h":"دُعَاءُ الْمُقِيمِ لِلْمُسَافِرِ","s":"رواه الترمذي وأحمد، وصححه الألباني"},{"t":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ","c":1,"h":"دُعَاءُ النُّزُولِ فِي مَكَانٍ","s":"رواه مسلم من حديث خولة بنت حكيم"},{"t":"رَبِّ اغْفِرْ لِي رَبِّ اغْفِرْ لِي اللَّهُمَّ اغْفِرْ لِي ، وَارْحَمْنِي وَاهْدِنِي وَاجْبُرْنِي وَعَافِنِي وَارْزُقْنِي وَارْفَعْنِي","c":1,"h":"الدُّعَاءُ بَيْنَ السَّجْدَتَيْنِ","s":"رواه أبو داود والترمذي وابن ماجه، وصححه الألباني"},{"t":"اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا","c":1,"h":"دُعَاءُ مَنِ اسْتَصْعَبَ عَلَيْهِ أَمْرٌ","s":"رواه ابن حبان في صحيحه وابن السني من حديث أنس"},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ","c":1,"h":"دُعَاءُ الْخَوْفِ مِنَ الشِّرْكِ","s":"رواه أحمد والبخاري في الأدب المفرد، وصححه الألباني"},{"t":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ (100 مَرَّةٍ قَبْلَ أَنْ يَقُومَ)","c":100,"h":"مَا يُقَالُ فِي الْمَجْلِسِ","s":"رواه أبو داود والترمذي من حديث ابن عمر، وصححه الألباني"},{"t":"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ","c":1,"h":"كَفَّارَةُ الْمَجْلِسِ","s":"رواه أبو داود والترمذي، وصححه الألباني"},{"t":"الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلَاهُ بِهِ وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلًا","c":1,"h":"دُعَاءُ مَنْ رَأَى مُبْتَلًى","s":"رواه الترمذي، وحسّنه الألباني"},{"t":"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","c":1,"h":"دُعَاءُ الْغَضَبِ","s":"متفق عليه من حديث سليمان بن صُرَد"},{"t":"بَارَكَ اللَّهُ لَكَ ، وَبَارَكَ عَلَيْكَ ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ","c":1,"h":"الدُّعَاءُ لِلْمُتَزَوِّجِ","s":"رواه أبو داود والترمذي من حديث أبي هريرة، وصححه الألباني"},{"t":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ ، وَإِذَا اشْتَرَى بَعِيرًا فَلْيَأْخُذْ بِذُرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ","c":1,"h":"دُعَاءُ الْمُتَزَوِّجِ لِنَفْسِهِ","s":"رواه أبو داود وابن ماجه، وحسّنه الألباني"},{"t":"بِسْمِ اللَّهِ ـ اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا","c":1,"h":"الدُّعَاءُ قَبْلَ الْجِمَاعِ","s":"متفق عليه من حديث ابن عباس"},{"t":"إِذَا عَطَسَ أَحَدُكُمْ فَلْيَقُلْ : الْحَمْدُ لِلَّهِ ، وَلْيَقُلْ لَهُ أَخُوهُ ، أَوْ صَاحِبُهُ : يَرْحَمُكَ اللَّهُ فَإِذَا قَالَ لَهُ : يَرْحَمُكَ اللَّهُ ، فَلْيَقُلْ : يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ.","c":1,"h":"دُعَاءُ الْعُطَاسِ","s":"رواه البخاري من حديث أبي هريرة"},{"t":"ذَهَبَ الظَّمَأُ ، وَابْتَلَّتِ الْعُرُوقُ ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ","c":1,"h":"الدُّعَاءُ عِنْدَ إِفْطَارِ الصَّائِمِ","s":"رواه أبو داود من حديث ابن عمر، وحسّنه الألباني"},{"t":"أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ","c":1,"h":"الدُّعَاءُ إِذَا أَفْطَرَ عِنْدَ أَهْلِ بَيْتٍ","s":"رواه أبو داود وأحمد من حديث أنس، وصححه الألباني"},{"t":"اللَّهُ أَكْبَرُ ، اللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِالْأَمْنِ ، وَالْإِيمَانِ وَالسَّلَامَةِ ، وَالْإِسْلَامِ ، وَالتَّوْفِيقِ لِمَا تُحِبُّ وَتَرْضَى رَبُّنَا وَرَبُّكَ اللَّهُ.","c":1,"h":"دُعَاءُ رُؤْيَةِ الْهِلَالِ","s":"رواه الترمذي والدارمي، وصححه الألباني"},{"t":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا","c":1,"h":"دُعَاءُ مَنْ أُصِيبَ بِمُصِيبَةٍ","s":"رواه مسلم من حديث أم سلمة"},{"t":"لَا بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ مَا مِنْ عَبْدٍ مُسْلِمٍ يَعُودُ مَرِيضًا لَمْ يَحْضُرْ أَجَلُهُ فَيَقُولُ سَبْعَ مَرَّاتٍ : أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ إِلَّا عُوفِيَ.","c":1,"h":"الدُّعَاءُ لِلْمَرِيضِ فِي عِيَادَتِهِ","s":"«لا بأس طهور» رواه البخاري، والدعاء سبعًا رواه أبو داود والترمذي، وصححه الألباني"},{"t":"اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى","c":1,"h":"دُعَاءُ الْمَرِيضِ الَّذِي يَئِسَ مِنْ حَيَاتِهِ","s":"متفق عليه من حديث عائشة"},{"t":"أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ","c":1,"h":"مَا يُعَوَّذُ بِهِ الْأَوْلَادُ","s":"رواه البخاري من حديث ابن عباس"},{"t":"حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ\nاللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ\nاللَّهُمَّ أَنْتَ عَضُدِي ، وَأَنْتَ نَصِيرِي ، بِكَ أَجُولُ وَبِكَ أَصُولُ وَبِكَ أُقَاتِلُ","c":1,"h":"دُعَاءُ لِقَاءِ الْعَدُوِّ وَذِي السُّلْطَانِ","s":"«حسبنا الله ونعم الوكيل» رواه البخاري، والبقية رواها أبو داود والترمذي، وصححه الألباني"},{"t":"قَالَ جَابِرُ بْنُ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا : كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا الِاسْتِخَارَةَ فِي الْأُمُورِ كُلِّهَا كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ ، يَقُولُ : ( إِذَا هَمَّ أَحَدُكُمْ بِالْأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ ثُمَّ لْيَقُلْ : اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ وَتَعْلَمُ وَلَا أَعْلَمُ وَأَنْتَ عَلَّامُ الْغُيُوبِ ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ ـ وَيُسَمِّي حَاجَتَهُ ـ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي ـ أَوْ قَالَ عَاجِلِهِ وَآجِلِهِ ـ فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي ـ أَوْ قَالَ عَاجِلِهِ وَآجِلِهِ ـ فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِي بِهِ).","c":1,"h":"دُعَاءُ صَلَاةِ الِاسْتِخَارَةِ","s":"رواه البخاري من حديث جابر"},{"t":"سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ ،وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ ( فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ )","c":1,"h":"دُعَاءُ سُجُودِ التِّلَاوَةِ","s":"رواه الترمذي وأحمد، وصححه الألباني، و«فتبارك الله أحسن الخالقين» عند الحاكم"},{"t":"اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْغَرْبِ ، اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْنِي مِنْ خَطَايَايَ بِالثَّلْجِ وَالْمَاءِ وَالْبَرَدِ.\nسُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ اسْمُكَ وَتَعَالَى جَدُّكَ وَلَا إِلَهَ غَيْرُكَ.\nاللَّهُ أَكْبَرُ كَبِيرًا ، اللَّهُ أَكْبَرُ كَبِيرًا ، اللَّهُ أَكْبَرُ كَبِيرًا ، وَالْحَمْدُ لِلَّهِ كَثِيرًا ، وَالْحَمْدُ لِلَّهِ كَثِيرًا ، وَالْحَمْدُ لِلَّهِ كَثِيرًا ، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا(ثَلَاثًا) ـ \"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ مِنْ نَفْخِهِ وَنَفْثِهِ وَهَمْزِهِ \".","c":1,"h":"دُعَاءُ الِاسْتِفْتَاحِ","s":"متفق عليه، و«سبحانك اللهم وبحمدك…» عند أهل السنن، وصححه الألباني"},{"t":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ حَيٌّ لَا يَمُوتُ بِيَدِهِ الْخَيْرُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ (كَتَبَ اللَّهُ لَهُ أَلْفَ أَلْفِ حَسَنَةٍ وَمَحَا عَنْهُ أَلْفَ أَلْفِ سَيِّئَةٍ وَرَفَعَ لَهُ أَلْفَ أَلْفِ دَرَجَةٍ وَفِي رِوَايَةٍ: وَبَنَى لَهُ بَيْتًا فِي الْجَنَّةِ).\nبِسْمِ اللَّهِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذِهِ السُّوقِ، وَخَيْرَ مَا فِيهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيهَا، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُصِيبَ بِهَا يَمِينًا فَاجِرَةً، أَوْ صَفْقَةً خَاسِرَةً.","c":1,"h":"دُعَاءُ دُخُولِ السُّوقِ","s":"رواه الترمذي وابن ماجه، وحسّنه الألباني"},{"t":"كَمَا أَخْبَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ((مَا مِنْ عَبْدٍ يُذْنِبُ ذَنْبًا فَيَتَوَضَّأُ فَيُحْسِنُ الطُّهُورَ،ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ ، ثُمَّ يَسْتَغْفِرُ اللَّهَ لِذَلِكَ الذَّنْبِ إِلَّا غُفِرَ لَهُ )).","c":1,"h":"عِنْدَ فِعْلِ الذَّنْبِ أَوِ ارْتِكَابِ الْمَعْصِيَةِ","s":"رواه أبو داود والترمذي من حديث أبي بكر الصديق، وصححه الألباني"},{"t":"الدُّعَاءُ عِنْدَ صِيَاحِ الدِّيكِ : (( اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ )). ((إِذَا سَمِعْتُمْ صِيَاحَ الدِّيكِ[مِنَ اللَّيْلِ]،فَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ فَإِنَّهَا رَأَتْ مَلَكًا وَإِذَا سَمِعْتُمْ نَهِيقَ الْحِمَارِ،فَتَعَوَّذُوا بِاللَّهِ مِنَ الشَّيْطَانِ فَإِنَّهَا رَأَتْ شَيْطَانًا)). مُتَّفَقٌ عَلَيْهِ.\nالدُّعَاءُ عِنْدَ صِيَاحِ الدِّيكِ وَنَهِيقِ الْحِمَارِ وَنُبَاحِ الْكِلَابِ: (( أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ )).\n((إِذَا سَمِعْتُمْ نُبَاحَ الْكِلَابِ وَنَهِيقَ الْحَمِيرِ بِاللَّيْلِ فَتَعَوَّذُوا بِاللَّهِ فَإِنَّهُنَّ يَرَيْنَ مَا لَا تَرَوْنَ)). صَحِيحٌ(صَحِيحُ سُنَنِ أَبِي دَاوُدَ3/961)","c":1,"h":"الدُّعَاءُ عِنْدَ سَمَاعِ أَصْوَاتِ الْحَيَوَانَاتِ","s":"متفق عليه، ونباح الكلاب عند أبي داود، وصححه الألباني"},{"t":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ ، خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ بِذَنْبِي ، فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ.\nعَنْ شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ ( سَيِّدُ الِاسْتِغْفَارِ أَنْ يَقُولَ الْعَبْدُ اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ ، خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ بِذَنْبِي ، فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ ) مَنْ قَالَهَا فِي النَّهَارِ مُوقِنًا بِهَا فَمَاتَ مِنْ يَوْمِهِ قَبْلَ أَنْ يُمْسِيَ فَهُوَ مِنْ أَهْلِ الْجَنَّةِ وَمَنْ قَالَهَا مِنَ اللَّيْلِ وَهُوَ مُوقِنٌ بِهَا فَمَاتَ قَبْلَ أَنْ يُصْبِحَ فَهُوَ مِنْ أَهْلِ الْجَنَّةِ . أَخْرَجَهُ الْبُخَارِيُّ.","c":1,"h":"سَيِّدُ الِاسْتِغْفَارِ","s":"رواه البخاري من حديث شداد بن أوس"},{"t":"ضَعْ يَدَكَ عَلَى الَّذِي تَأَلَّمَ مِنْ جَسَدِكَ وَقُلْ: بِسْمِ اللَّهِ ،ثَلَاثًا ،وَقُلْ سَبْعَ مَرَّاتٍ: أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ.","c":1,"h":"الدُّعَاءُ إِذَا أَحْسَسْتَ بِوَجَعٍ فِي جَسَدِكَ","s":"رواه مسلم من حديث عثمان بن أبي العاص"},{"t":"مَا مِنْ عَبْدٍ يُذْنِبُ ذَنْبًا فَيُحْسِنُ الطُّهُورَ ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ ، ثُمَّ يَسْتَغْفِرُ اللَّهَ إِلَّا غُفِرَ لَهُ","c":1,"h":"مَا يَقُولُ وَيَفْعَلُ مَنْ أَذْنَبَ ذَنْبًا","s":"رواه أبو داود والترمذي من حديث أبي بكر الصديق، وصححه الألباني"}]},{"k":"nabawi","ar":"أدعية نبوية","en":"Prophetic duas","items":[{"t":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ.","c":1,"s":"رَوَاهُ الْبُخَارِيُّ (6306) عَنْ شَدَّادِ بْنِ أَوْسٍ وَقَدْ وَصَفَ النَّبِيُّ هَذَا الدُّعَاءَ بِأَنَّهُ سَيِّدُ الِاسْتِغْفَارِ."},{"t":"اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ.","c":1,"s":"رَوَاهُ الْبُخَارِيُّ (834) وَمُسْلِمٌ (6869) عَنْ أَبِي بَكْرٍ."},{"t":"رَبِّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي وَإِسْرَافِي فِي أَمْرِي كُلِّهِ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، اللَّهُمَّ اغْفِرْ لِي خَطَايَايَ وَعَمْدِي وَجَهْلِي وَهَزْلِي، وَكُلُّ ذَلِكَ عِنْدِي، اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.","c":1,"s":"رَوَاهُ الْبُخَارِيُّ (6398) وَمُسْلِمٌ (6901) عَنْ أَبِي مُوسَى."},{"t":"اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ، دِقَّهُ، وَجِلَّهُ، وَأَوَّلَهُ، وَآخِرَهُ، وَعَلَانِيَتَهُ، وَسِرَّهُ.","c":1,"s":"رَوَاهُ مُسْلِمٌ (1084) عَنْ أَبِي هُرَيْرَةَ."},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ.","c":1,"s":"رَوَاهُ الْبُخَارِيُّ (6369) عَنْ أَنَسٍ."},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُخْلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ.","c":1,"s":"رَوَاهُ الْبُخَارِيُّ (6365) عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ."},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكَسَلِ وَالْهَرَمِ وَالْمَأْثَمِ وَالْمَغْرَمِ، وَمِنْ فِتْنَةِ الْقَبْرِ وَعَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ النَّارِ وَعَذَابِ النَّارِ، وَمِنْ شَرِّ فِتْنَةِ الْغِنَى، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْفَقْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، اللَّهُمَّ اغْسِلْ عَنِّي خَطَايَايَ بِمَاءِ الثَّلْجِ وَالْبَرَدِ، وَنَقِّ قَلْبِي مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَبَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ.","c":1,"s":"رَوَاهُ الْبُخَارِيُّ (6368) وَمُسْلِمٌ (6871) عَنْ عَائِشَةَ."},{"t":"اللَّهُمَّ رَبَّ السَّمَوَاتِ وَرَبَّ الْأَرْضِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، اللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ.","c":1,"s":"رَوَاهُ مُسْلِمٌ (6889) عَنْ أَبِي هُرَيْرَةَ."},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ.","c":1,"s":"رَوَاهُ مُسْلِمٌ (6895) عَنْ عَائِشَةَ."},{"t":"اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ.","c":1,"s":"رَوَاهُ مُسْلِمٌ (6903) عَنْ أَبِي هُرَيْرَةَ."},{"t":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى.","c":1,"s":"رَوَاهُ مُسْلِمٌ (6904) عَنِ ابْنِ مَسْعُودٍ."},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَالْجُبْنِ وَالْبُخْلِ، وَالْهَرَمِ وَعَذَابِ الْقَبْرِ، اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا.","c":1,"s":"رَوَاهُ مُسْلِمٌ (6906) عَنْ زَيْدِ بْنِ أَرْقَمَ."},{"t":"اللَّهُمَّ لَكَ أَسْلَمْتُ وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ وَإِلَيْكَ أَنَبْتُ وَبِكَ خَاصَمْتُ، اللَّهُمَّ إِنِّي أَعُوذُ بِعِزَّتِكَ لَا إِلَهَ إِلَّا أَنْتَ أَنْ تُضِلَّنِي، أَنْتَ الْحَيُّ الَّذِي لَا يَمُوتُ وَالْجِنُّ وَالْإِنْسُ يَمُوتُونَ.","c":1,"s":"رَوَاهُ الْبُخَارِيُّ (7383) وَمُسْلِمٌ (6899) عَنِ ابْنِ عَبَّاسٍ."},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ وَتَحَوُّلِ عَافِيَتِكَ وَفُجَاءَةِ نِقْمَتِكَ وَجَمِيعِ سَخَطِكَ.","c":1,"s":"رَوَاهُ مُسْلِمٌ (6943) عَنِ ابْنِ عُمَرَ."},{"t":"اللَّهُمَّ مُصَرِّفَ الْقُلُوبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ.","c":1,"s":"رَوَاهُ مُسْلِمٌ (6750) عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو."},{"t":"اللَّهُمَّ رَبَّ جَبْرَائِيلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ، فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ، اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ، إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ.","c":1,"s":"رَوَاهُ مُسْلِمٌ (1811) عَنْ عَائِشَةَ."},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ.","c":1,"s":"رَوَاهُ مُسْلِمٌ (1090) عَنْ عَائِشَةَ."},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَهْدِ الْبَلَاءِ وَدَرَكِ الشَّقَاءِ وَسُوءِ الْقَضَاءِ وَشَمَاتَةِ الْأَعْدَاءِ.","c":1,"s":"رَوَاهُ الْبُخَارِيُّ (6347) وَمُسْلِمٌ (6877) عَنْ أَبِي هُرَيْرَةَ."},{"t":"اللَّهُمَّ اجْعَلْ لِي فِي قَلْبِي نُورًا، وَفِي لِسَانِي نُورًا، وَفِي سَمْعِي نُورًا، وَفِي بَصَرِي نُورًا، وَمِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ شِمَالِي نُورًا، وَمِنْ بَيْنِ يَدَيَّ نُورًا، وَمِنْ خَلْفِي نُورًا، وَاجْعَلْ فِي نَفْسِي نُورًا، وَأَعْظِمْ لِي نُورًا.","c":1,"s":"رَوَاهُ الْبُخَارِيُّ (6316) وَمُسْلِمٌ (1797) عَنِ ابْنِ عَبَّاسٍ."},{"t":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا عَاذَ بِهِ عَبْدُكَ وَنَبِيُّكَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِي خَيْرًا.","c":1,"s":"رَوَاهُ ابْنُ مَاجَهْ (3846) بِإِسْنَادٍ صَحِيحٍ عَنْ عَائِشَةَ."},{"t":"اللَّهُمَّ بِعِلْمِكَ الْغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي، اللَّهُمَّ وَأَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَى، وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَاءَ بَعْدَ الْقَضَاءِ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ وَالشَّوْقَ إِلَى لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ وَلَا فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَّا بِزِينَةِ الْإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ.","c":1,"s":"رَوَاهُ النَّسَائِيُّ (1305) بِإِسْنَادٍ حَسَنٍ عَنْ عَمَّارِ بْنِ يَاسِرٍ."},{"t":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي، وَاحْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.","c":1,"s":"رَوَاهُ أَبُو دَاوُدَ (5074) وَغَيْرُهُ بِإِسْنَادٍ صَحِيحٍ عَنِ ابْنِ عُمَرَ."},{"t":"اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَشَرِّ الشَّيْطَانِ وَشِرْكِهِ.","c":1,"s":"رَوَاهُ التِّرْمِذِيُّ (3392) وَغَيْرُهُ بِإِسْنَادٍ صَحِيحٍ عَنْ أَبِي هُرَيْرَةَ."},{"t":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ، وَالْعَزِيمَةَ عَلَى الرُّشْدِ، وَأَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ، وَحُسْنَ عِبَادَتِكَ، وَأَسْأَلُكَ قَلْبًا سَلِيمًا، وَلِسَانًا صَادِقًا، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ، إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ.","c":1,"s":"رَوَاهُ الطَّبَرَانِيُّ فِي \"الْكَبِيرِ\" (7135) عَنْ شَدَّادِ بْنِ أَوْسٍ.","f":"disp","w":"مختلف في ثبوته: في إسناده مقال، وصححه بعضهم بمجموع طرقه"},{"t":"اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ.","c":1,"s":"رَوَاهُ التِّرْمِذِيُّ (3563) بِإِسْنَادٍ حَسَنٍ عَنْ عَلِيٍّ."},{"t":"اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ.","c":1,"s":"رَوَاهُ أَبُو دَاوُدَ (5090) بِإِسْنَادٍ حَسَنٍ عَنْ أَبِي بَكْرَةَ."},{"t":"رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ، وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ، وَاهْدِنِي وَيَسِّرِ الْهُدَى لِي، وَانْصُرْنِي عَلَى مَنْ بَغَى عَلَيَّ، رَبِّ اجْعَلْنِي لَكَ شَكَّارًا، لَكَ ذَكَّارًا، لَكَ رَهَّابًا، لَكَ مِطْوَاعًا، لَكَ مُخْبِتًا إِلَيْكَ أَوَّاهًا مُنِيبًا، رَبِّ تَقَبَّلْ تَوْبَتِي وَاغْسِلْ حَوْبَتِي وَأَجِبْ دَعْوَتِي وَثَبِّتْ حُجَّتِي وَسَدِّدْ لِسَانِي وَاهْدِ قَلْبِي وَاسْلُلْ سَخِيمَةَ صَدْرِي.","c":1,"s":"رَوَاهُ التِّرْمِذِيُّ (3551) وَغَيْرُهُ بِإِسْنَادٍ صَحِيحٍ عَنِ ابْنِ عَبَّاسٍ."},{"t":"اللَّهُمَّ لَكَ الْحَمْدُ كُلُّهُ، اللَّهُمَّ لَا قَابِضَ لِمَا بَسَطْتَ، وَلَا بَاسِطَ لِمَا قَبَضْتَ، وَلَا هَادِيَ لِمَا أَضْلَلْتَ، وَلَا مُضِلَّ لِمَنْ هَدَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُقَرِّبَ لِمَا بَاعَدْتَ، وَلَا مُبَاعِدَ لِمَا قَرَّبْتَ، اللَّهُمَّ ابْسُطْ عَلَيْنَا مِنْ بَرَكَاتِكَ وَرَحْمَتِكَ وَفَضْلِكَ وَرِزْقِكَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ الْمُقِيمَ الَّذِي لَا يَحُولُ وَلَا يَزُولُ، اللَّهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ يَوْمَ الْعَيْلَةِ، وَالْأَمْنَ يَوْمَ الْخَوْفِ، اللَّهُمَّ إِنِّي عَائِذٌ بِكَ مِنْ شَرِّ مَا أَعْطَيْتَنَا وَشَرِّ مَا مَنَعْتَ، اللَّهُمَّ حَبِّبْ إِلَيْنَا الْإِيمَانَ وَزَيِّنْهُ فِي قُلُوبِنَا، وَكَرِّهْ إِلَيْنَا الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ، وَاجْعَلْنَا مِنَ الرَّاشِدِينَ، اللَّهُمَّ تَوَفَّنَا مُسْلِمِينَ، وَأَحْيِنَا مُسْلِمِينَ، وَأَلْحِقْنَا بِالصَّالِحِينَ غَيْرَ خَزَايَا وَلَا مَفْتُونِينَ، اللَّهُمَّ قَاتِلْ الْكَفَرَةَ الَّذِينَ يُكَذِّبُونَ رُسُلَكَ، وَيَصُدُّونَ عَنْ سَبِيلِكَ، وَاجْعَلْ عَلَيْهِمْ رِجْزَكَ وَعَذَابَكَ، اللَّهُمَّ قَاتِلْ الْكَفَرَةَ الَّذِينَ أُوتُوا الْكِتَابَ إِلَهَ الْحَقِّ.","c":1,"s":"رَوَاهُ الْإِمَامُ أَحْمَدُ (15492) عَنْ رِفَاعَةَ الزُّرَقِيِّ بِإِسْنَادٍ صَحِيحٍ.","f":"disp","w":"مختلف في ثبوته: صححه الحاكم، وضعّف إسناده الألباني"},{"t":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ.","c":1,"s":"رَوَاهُ الْبُخَارِيُّ (3370) وَمُسْلِمٌ (908) عَنْ كَعْبِ بْنِ عُجْرَةَ."}]},{"k":"qurani","ar":"الأدعية القرآنية","en":"Quranic duas","items":[{"t":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","c":1,"s":"القرآن الكريم — سورة البقرة: 201"},{"t":"رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ","c":1,"s":"القرآن الكريم — سورة البقرة: 250"},{"t":"رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ","c":1,"s":"القرآن الكريم — سورة البقرة: 286"},{"t":"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ الْوَهَّابُ","c":1,"s":"القرآن الكريم — سورة آل عمران: 8"},{"t":"رَبَّنَا إِنَّنَا آمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ","c":1,"s":"القرآن الكريم — سورة آل عمران: 16"},{"t":"رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً ۖ إِنَّكَ سَمِيعُ الدُّعَاءِ","c":1,"s":"القرآن الكريم — سورة آل عمران: 38"},{"t":"رَبَّنَا آمَنَّا بِمَا أَنزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِدِينَ","c":1,"s":"القرآن الكريم — سورة آل عمران: 53"},{"t":"رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ","c":1,"s":"القرآن الكريم — سورة آل عمران: 147"},{"t":"رَبَّنَا مَا خَلَقْتَ هَٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ ۖ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا ۚ رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ ۗ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ","c":1,"s":"القرآن الكريم — سورة آل عمران: 191-194"},{"t":"رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ","c":1,"s":"القرآن الكريم — سورة الأعراف: 23"},{"t":"رَبَّنَا لَا تَجْعَلْنَا مَعَ الْقَوْمِ الظَّالِمِينَ","c":1,"s":"القرآن الكريم — سورة الأعراف: 47"},{"t":"رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ","c":1,"s":"القرآن الكريم — سورة الأعراف: 126"},{"t":"حَسْبِيَ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ ۖ عَلَيْهِ تَوَكَّلْتُ ۖ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ","c":1,"s":"القرآن الكريم — سورة التوبة: 129"},{"t":"رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ الظَّالِمِينَ وَنَجِّنَا بِرَحْمَتِكَ مِنَ الْقَوْمِ الْكَافِرِينَ","c":1,"s":"القرآن الكريم — سورة يونس: 85-86"},{"t":"رَبِّ إِنِّي أَعُوذُ بِكَ أَنْ أَسْأَلَكَ مَا لَيْسَ لِي بِهِ عِلْمٌ ۖ وَإِلَّا تَغْفِرْ لِي وَتَرْحَمْنِي أَكُن مِّنَ الْخَاسِرِينَ","c":1,"s":"القرآن الكريم — سورة هود: 47"},{"t":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِن ذُرِّيَّتِي ۚ رَبَّنَا وَتَقَبَّلْ دُعَاءِ","c":1,"s":"القرآن الكريم — سورة إبراهيم: 40"},{"t":"رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ","c":1,"s":"القرآن الكريم — سورة إبراهيم: 41"},{"t":"رَّبِّ أَدْخِلْنِي مُدْخَلَ صِدْقٍ وَأَخْرِجْنِي مُخْرَجَ صِدْقٍ وَاجْعَل لِّي مِن لَّدُنكَ سُلْطَانًا نَّصِيرًا","c":1,"s":"القرآن الكريم — سورة الإسراء: 80"},{"t":"رَبَّنَا آتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا","c":1,"s":"القرآن الكريم — سورة الكهف: 10"},{"t":"رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِّن لِّسَانِي يَفْقَهُوا قَوْلِي","c":1,"s":"القرآن الكريم — سورة طه: 25-28"},{"t":"رَّبِّ زِدْنِي عِلْمًا","c":1,"s":"القرآن الكريم — سورة طه: 114"},{"t":"لَا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ","c":1,"s":"القرآن الكريم — سورة الأنبياء: 87"},{"t":"رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنتَ خَيْرُ الْوَارِثِينَ","c":1,"s":"القرآن الكريم — سورة الأنبياء: 89"},{"t":"رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَعُوذُ بِكَ رَبِّ أَن يَحْضُرُونِ","c":1,"s":"القرآن الكريم — سورة المؤمنون: 97-98"},{"t":"رَبَّنَا آمَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ الرَّاحِمِينَ","c":1,"s":"القرآن الكريم — سورة المؤمنون: 109"},{"t":"رَّبِّ اغْفِرْ وَارْحَمْ وَأَنتَ خَيْرُ الرَّاحِمِينَ","c":1,"s":"القرآن الكريم — سورة المؤمنون: 118"}]},{"k":"anbiya","ar":"أدعية الأنبياء","en":"Duas of the prophets","items":[{"t":"رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ","c":1,"h":"آدم عليه السلام","s":"القرآن الكريم — سورة الأعراف: 23"},{"t":"\"رَّبِّ اغْفِرْ لِي وَلِوَالِدَيَّ وَلِمَن دَخَلَ بَيْتِيَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَلَا تَزِدِ الظَّالِمِينَ إِلَّا تَبَارًا\". [نُوحٍ - 28].\n\" رَبِّ إِنِّي أَعُوذُ بِكَ أَنْ أَسْأَلَكَ مَا لَيْسَ لِي بِهِ عِلْمٌ وَإِلَّا تَغْفِرْ لِي وَتَرْحَمْنِي أَكُن مِّنَ الْخَاسِرِينَ\". [هُودٍ - 47].\n\"رَّبِّ أَنزِلْنِي مُنزَلًا مُّبَارَكًا وَأَنتَ خَيْرُ الْمُنزِلِينَ\". [الْمُؤْمِنُونَ - 29].","c":1,"h":"نوح عليه السلام","s":"آيات من القرآن الكريم (المواضع مذكورة في النص)"},{"t":"\"رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ (127) رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَا أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَا إِنَّكَ أَنتَ التَّوَّابُ الرَّحِيمُ (128)\". [الْبَقَرَةِ - 127-128].\n\"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِن ذُرِّيَّتِي ۚ رَبَّنَا وَتَقَبَّلْ دُعَاءِ (40) رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ (41)\". [إِبْرَاهِيمَ - 40-41].\n\"رَبِّ هَبْ لِي حُكْمًا وَأَلْحِقْنِي بِالصَّالِحِينَ (83) وَاجْعَل لِّي لِسَانَ صِدْقٍ فِي الْآخِرِينَ (84) وَاجْعَلْنِي مِن وَرَثَةِ جَنَّةِ النَّعِيمِ (85)\". [الشُّعَرَاءِ - 83-85].\n\"رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ الْمَصِيرُ (4) رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا وَاغْفِرْ لَنَا رَبَّنَا ۖ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ (5)\". [الْمُمْتَحَنَةِ - 4-5].\n\"رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ\". [الصَّافَّاتِ - 100].","c":1,"h":"إبراهيم عليه السلام","s":"آيات من القرآن الكريم (المواضع مذكورة في النص)"},{"t":"إِنِّي تَوَكَّلْتُ عَلَى اللَّهِ رَبِّي وَرَبِّكُم ۚ مَّا مِن دَابَّةٍ إِلَّا هُوَ آخِذٌ بِنَاصِيَتِهَا ۚ إِنَّ رَبِّي عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ","c":1,"h":"هود عليه السلام","s":"القرآن الكريم — سورة هود: 56"},{"t":"\"رَبِّ انصُرْنِي عَلَى الْقَوْمِ الْمُفْسِدِينَ\". [الْعَنْكَبُوتِ - 30].\n\"رَبِّ نَجِّنِي وَأَهْلِي مِمَّا يَعْمَلُونَ\". [الشُّعَرَاءِ - 169].","c":1,"h":"لوط عليه السلام","s":"آيات من القرآن الكريم (المواضع مذكورة في النص)"},{"t":"فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ أَنتَ وَلِيِّي فِي الدُّنْيَا وَالْآخِرَةِ ۖ تَوَفَّنِي مُسْلِمًا وَأَلْحِقْنِي بِالصَّالِحِينَ","c":1,"h":"يوسف عليه السلام","s":"القرآن الكريم — سورة يوسف: 101"},{"t":"وَسِعَ رَبُّنَا كُلَّ شَيْءٍ عِلْمًا عَلَى اللَّهِ تَوَكَّلْنَا رَبَّنَا افْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِالْحَقِّ وَأَنتَ خَيْرُ الْفَاتِحِينَ","c":1,"h":"شعيب عليه السلام","s":"القرآن الكريم — سورة الأعراف: 89"},{"t":"\"رَبِّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي\". [الْقَصَصِ - 16].\n\"رَبِّ بِمَا أَنْعَمْتَ عَلَيَّ فَلَنْ أَكُونَ ظَهِيرًا لِّلْمُجْرِمِينَ\". [الْقَصَصِ - 17].\n\"رَبِّ إِنِّي لِمَا أَنزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ\". [الْقَصَصِ - 24].\n\"رَبِّ اشْرَحْ لِي صَدْرِي (25) وَيَسِّرْ لِي أَمْرِي (26) وَاحْلُلْ عُقْدَةً مِّن لِّسَانِي (27) يَفْقَهُوا قَوْلِي (28)\". [طه - 25-28].","c":1,"h":"موسى عليه السلام","s":"آيات من القرآن الكريم (المواضع مذكورة في النص)"},{"t":"أَنِّي مَسَّنِيَ الضُّرُّ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ","c":1,"h":"أيوب عليه السلام","s":"القرآن الكريم — سورة الأنبياء: 83"},{"t":"رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَدْخِلْنِي بِرَحْمَتِكَ فِي عِبَادِكَ الصَّالِحِينَ","c":1,"h":"سليمان عليه السلام","s":"القرآن الكريم — سورة النمل: 19"},{"t":"لَا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ","c":1,"h":"يونس عليه السلام","s":"القرآن الكريم — سورة الأنبياء: 87"},{"t":"\"رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ الدُّعَاءِ\". [آلِ عِمْرَانَ - 38].\n\"رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنتَ خَيْرُ الْوَارِثِينَ\". [الْأَنْبِيَاءِ - 89].","c":1,"h":"زكريا عليه السلام","s":"آيات من القرآن الكريم (المواضع مذكورة في النص)"},{"t":"إِنَّمَا أَشْكُو بَثِّي وَحُزْنِي إِلَى اللَّهِ","c":1,"h":"يعقوب عليه السلام","s":"القرآن الكريم — سورة يوسف: 86"}]},{"k":"mayyit","ar":"أدعية للميّت","en":"For the deceased","items":[{"t":"اللَّهُمَّ أَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ وَمِنْ عَذَابِ النَّارِ.\nاللَّهُمَّ عَامِلْهُ بِمَا أَنْتَ أَهْلُهُ، وَلَا تُعَامِلْهُ بِمَا هُوَ أَهْلُهُ.\nاللَّهُمَّ اجْزِهِ عَنِ الْإِحْسَانِ إِحْسَانًا وَعَنِ الْإِسَاءَةِ عَفْوًا وَغُفْرَانًا.\nاللَّهُمَّ إِنْ كَانَ مُحْسِنًا فَزِدْ مِنْ حَسَنَاتِهِ، وَإِنْ كَانَ مُسِيئًا فَتَجَاوَزْ عَنْ سَيِّئَاتِهِ.\nاللَّهُمَّ أَدْخِلْهُ الْجَنَّةَ مِنْ غَيْرِ مُنَاقَشَةِ حِسَابٍ وَلَا سَابِقَةِ عَذَابٍ.\nاللَّهُمَّ آنِسْهُ فِي وَحْدَتِهِ وَفِي وَحْشَتِهِ وَفِي غُرْبَتِهِ.\nاللَّهُمَّ أَنْزِلْهُ مُنْزَلًا مُبَارَكًا وَأَنْتَ خَيْرُ الْمُنْزِلِينَ.\nاللَّهُمَّ أَنْزِلْهُ مَنَازِلَ الصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ، وَحَسُنَ أُولَئِكَ رَفِيقًا.\nاللَّهُمَّ اجْعَلْ قَبْرَهُ رَوْضَةً مِنْ رِيَاضِ الْجَنَّةِ، وَلَا تَجْعَلْهُ حُفْرَةً مِنْ حُفَرِ النَّارِ.\nاللَّهُمَّ افْسَحْ لَهُ فِي قَبْرِهِ مَدَّ بَصَرِهِ، وَافْرُشْ قَبْرَهُ مِنْ فِرَاشِ الْجَنَّةِ.\nاللَّهُمَّ أَعِذْهُ مِنْ عَذَابِ الْقَبْرِ، وَجَفَافِ الْأَرْضِ عَنْ جَنْبَيْهِ.\nاللَّهُمَّ امْلَأْ قَبْرَهُ بِالرِّضَا وَالنُّورِ وَالْفُسْحَةِ وَالسُّرُورِ.\nاللَّهُمَّ إِنَّهُ فِي ذِمَّتِكَ وَحَبْلِ جِوَارِكَ، فَقِهِ فِتْنَةَ الْقَبْرِ، وَعَذَابَ النَّارِ، وَأَنْتَ أَهْلُ الْوَفَاءِ وَالْحَقِّ، فَاغْفِرْ لَهُ وَارْحَمْهُ إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ.\nاللَّهُمَّ إِنَّهُ عَبْدُكَ وَابْنُ عَبْدِكَ خَرَجَ مِنَ الدُّنْيَا وَسَعَتِهَا وَمَحْبُوبِهَا وَأَحِبَّائِهِ فِيهَا إِلَى ظُلْمَةِ الْقَبْرِ وَمَا هُوَ لَاقِيهِ.\nاللَّهُمَّ إِنَّهُ كَانَ يَشْهَدُ أَنَّكَ لَا إِلَهَ إِلَّا أَنْتَ وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ وَأَنْتَ أَعْلَمُ بِهِ.\nاللَّهُمَّ إِنَّا نَتَوَسَّلُ بِكَ إِلَيْكَ، وَنُقْسِمُ بِكَ عَلَيْكَ أَنْ تَرْحَمَهُ وَلَا تُعَذِّبَهُ، وَأَنْ تُثَبِّتَهُ عِنْدَ السُّؤَالِ.\nاللَّهُمَّ إِنَّهُ نَزَلَ بِكَ وَأَنْتَ خَيْرُ مَنْزُولٍ بِهِ، وَأَصْبَحَ فَقِيرًا إِلَى رَحْمَتِكَ وَأَنْتَ غَنِيٌّ عَنْ عَذَابِهِ.\nاللَّهُمَّ آتِهِ بِرَحْمَتِكَ وَرِضَاكَ، وَقِهِ فِتْنَةَ الْقَبْرِ وَعَذَابَهُ، وَآتِهِ بِرَحْمَتِكَ الْأَمْنَ مِنْ عَذَابِكَ حَتَّى تَبْعَثَهُ إِلَى جَنَّتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ انْقُلْهُ مِنْ مَوَاطِنِ الدُّودِ وَضِيقِ اللُّحُودِ إِلَى جَنَّاتِ الْخُلُودِ.\nاللَّهُمَّ احْمِهِ تَحْتَ الْأَرْضِ، وَاسْتُرْهُ يَوْمَ الْعَرْضِ، وَلَا تُخْزِهِ يَوْمَ يُبْعَثُونَ \"يَوْمَ لَا يَنْفَعُ مَالٌ وَلَا بَنُونَ إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ\".\nاللَّهُمَّ يَمِّنْ كِتَابَهُ، وَيَسِّرْ حِسَابَهُ، وَثَقِّلْ بِالْحَسَنَاتِ مِيزَانَهُ، وَثَبِّتْ عَلَى الصِّرَاطِ أَقْدَامَهُ، وَأَسْكِنْهُ فِي أَعْلَى الْجَنَّاتِ بِجِوَارِ حَبِيبِكَ وَمُصْطَفَاكَ (صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ).\nاللَّهُمَّ أَمِّنْهُ مِنْ فَزَعِ يَوْمِ الْقِيَامَةِ، وَمِنْ هَوْلِ يَوْمِ الْقِيَامَةِ، وَاجْعَلْ نَفْسَهُ آمِنَةً مُطْمَئِنَّةً، وَلَقِّنْهُ حُجَّتَهُ.\nاللَّهُمَّ اجْعَلْهُ فِي بَطْنِ الْقَبْرِ مُطْمَئِنًّا وَعِنْدَ قِيَامِ الْأَشْهَادِ آمِنًا، وَبِجُودِ رِضْوَانِكَ وَاثِقًا، وَإِلَى أَعْلَى دَرَجَاتِكَ سَابِقًا.\nاللَّهُمَّ اجْعَلْ عَنْ يَمِينِهِ نُورًا حَتَّى تَبْعَثَهُ آمِنًا مُطْمَئِنًّا فِي نُورٍ مِنْ نُورِكَ.\nاللَّهُمَّ انْظُرْ إِلَيْهِ نَظْرَةَ رِضًا، فَإِنَّ مَنْ تَنْظُرُ إِلَيْهِ نَظْرَةَ رِضًا لَا تُعَذِّبُهُ أَبَدًا.\nاللَّهُمَّ أَسْكِنْهُ فَسِيحَ الْجِنَانِ، وَاغْفِرْ لَهُ يَا رَحْمَنُ، وَارْحَمْهُ يَا رَحِيمُ، وَتَجَاوَزْ عَمَّا تَعْلَمُ يَا عَلِيمُ.\nاللَّهُمَّ اعْفُ عَنْهُ فَإِنَّكَ الْقَائِلُ \"وَيَعْفُو عَنْ كَثِيرٍ\".\nاللَّهُمَّ إِنَّهُ جَاءَ بِبَابِكَ، وَأَنَاخَ بِجَنَابِكَ، فَجُدْ عَلَيْهِ بِعَفْوِكَ وَإِكْرَامِكَ وَجُودِ إِحْسَانِكَ.\nاللَّهُمَّ إِنَّ رَحْمَتَكَ وَسِعَتْ كُلَّ شَيْءٍ فَارْحَمْهُ رَحْمَةً تَطْمَئِنُّ بِهَا نَفْسُهُ، وَتَقَرُّ بِهَا عَيْنُهُ.\nاللَّهُمَّ احْشُرْهُ مَعَ الْمُتَّقِينَ إِلَى الرَّحْمَنِ وَفْدًا.\nاللَّهُمَّ احْشُرْهُ مَعَ أَصْحَابِ الْيَمِينِ، وَاجْعَلْ تَحِيَّتَهُ سَلَامٌ لَكَ مِنْ أَصْحَابِ الْيَمِينِ.\nاللَّهُمَّ بَشِّرْهُ بِقَوْلِكَ \"كُلُوا وَاشْرَبُوا هَنِيئًا بِمَا أَسْلَفْتُمْ فِي الْأَيَّامِ الْخَالِيَةِ\".\nاللَّهُمَّ اجْعَلْهُ مِنَ الَّذِينَ سُعِدُوا فِي الْجَنَّةِ خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ.\nاللَّهُمَّ لَا نُزَكِّيهِ عَلَيْكَ، وَلَكِنَّا نَحْسَبُهُ أَنَّهُ آمَنَ وَعَمِلَ صَالِحًا، فَاجْعَلْ لَهُ جَنَّتَيْنِ ذَوَاتَيْ أَفْنَانٍ بِحَقِّ قَوْلِكَ: \"وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ\".\nاللَّهُمَّ شَفِّعْ فِيهِ نَبِيَّنَا وَمُصْطَفَاكَ، وَاحْشُرْهُ تَحْتَ لِوَائِهِ، وَاسْقِهِ مِنْ يَدِهِ الشَّرِيفَةِ شَرْبَةً هَنِيئَةً لَا يَظْمَأُ بَعْدَهَا أَبَدًا.\nاللَّهُمَّ اجْعَلْهُ فِي جَنَّةِ الْخُلْدِ \"الَّتِي وُعِدَ الْمُتَّقُونَ كَانَتْ لَهُمْ جَزَاءً وَمَصِيرًا. لَهُمْ فِيهَا مَا يَشَاءُونَ خَالِدِينَ كَانَ عَلَى رَبِّكَ وَعْدًا مَسْؤُولًا\".\nاللَّهُمَّ إِنَّهُ صَبَرَ عَلَى الْبَلَاءِ فَلَمْ يَجْزَعْ، فَامْنَحْهُ دَرَجَةَ الصَّابِرِينَ الَّذِينَ يُوَفَّوْنَ أُجُورَهُمْ بِغَيْرِ حِسَابٍ فَإِنَّكَ الْقَائِلُ \"إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ\".\nاللَّهُمَّ إِنَّهُ كَانَ مُصَلِّيًا لَكَ، فَثَبِّتْهُ عَلَى الصِّرَاطِ يَوْمَ تَزِلُّ الْأَقْدَامُ.\nاللَّهُمَّ إِنَّهُ كَانَ صَائِمًا لَكَ، فَأَدْخِلْهُ الْجَنَّةَ مِنْ بَابِ الرَّيَّانِ.\nاللَّهُمَّ إِنَّهُ كَانَ لِكِتَابِكَ تَالِيًا وَسَامِعًا، فَشَفِّعْ فِيهِ الْقُرْآنَ، وَارْحَمْهُ مِنَ النِّيرَانِ، وَاجْعَلْهُ يَا رَحْمَنُ يَرْتَقِي فِي الْجَنَّةِ إِلَى آخِرِ آيَةٍ قَرَأَهَا أَوْ سَمِعَهَا، وَآخِرِ حَرْفٍ تَلَاهُ.\nاللَّهُمَّ ارْزُقْهُ بِكُلِّ حَرْفٍ فِي الْقُرْآنِ حَلَاوَةً، وَبِكُلِّ كَلِمَةٍ كَرَامَةً، وَبِكُلِّ آيَةٍ سَعَادَةً، وَبِكُلِّ سُورَةٍ سَلَامَةً، وَبِكُلِّ جُزْءٍ جَزَاءً.\nاللَّهُمَّ ارْحَمْهُ فَإِنَّهُ كَانَ مُسْلِمًا، وَاغْفِرْ لَهُ فَإِنَّهُ كَانَ مُؤْمِنًا، وَأَدْخِلْهُ الْجَنَّةَ فَإِنَّهُ كَانَ بِنَبِيِّكَ مُصَدِّقًا، وَسَامِحْهُ فَإِنَّهُ كَانَ لِكِتَابِكَ مُرَتِّلًا.\nاللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبِيرِنَا، وَذَكَرِنَا وَأُنْثَانَا.\nاللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلَامِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِيمَانِ.\nاللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُ وَلَا تُضْلِلْنَا بَعْدَهُ.\nاللَّهُمَّ ارْحَمْنَا إِذَا أَتَانَا الْيَقِينُ، وَعَرِقَ مِنَّا الْجَبِينُ، وَكَثُرَ الْأَنِينُ وَالْحَنِينُ.\nاللَّهُمَّ ارْحَمْنَا إِذَا يَئِسَ مِنَّا الطَّبِيبُ، وَبَكَى عَلَيْنَا الْحَبِيبُ، وَتَخَلَّى عَنَّا الْقَرِيبُ وَالْغَرِيبُ، وَارْتَفَعَ النَّشِيجُ وَالنَّحِيبُ.\nاللَّهُمَّ ارْحَمْنَا إِذَا اشْتَدَّتِ الْكُرُبَاتُ، وَتَوَالَتِ الْحَسَرَاتُ، وَأَطْبَقَتِ الرَّوْعَاتُ، وَفَاضَتِ الْعَبَرَاتُ، وَتَكَشَّفَتِ الْعَوْرَاتُ، وَتَعَطَّلَتِ الْقُوَى وَالْقُدُرَاتُ.\nاللَّهُمَّ ارْحَمْنَا إِذَا حُمِلْنَا عَلَى الْأَعْنَاقِ، وَبَلَغَتِ التَّرَاقِيَ، وَقِيلَ مَنْ رَاقٍ وَظَنَّ أَنَّهُ الْفِرَاقُ وَالْتَفَّتِ السَّاقُ بِالسَّاقِ، إِلَيْكَ يَا رَبَّنَا يَوْمَئِذٍ الْمَسَاقُ.\nاللَّهُمَّ ارْحَمْنَا إِذَا وُورِينَا التُّرَابَ، وَغُلِّقَتِ الْقُبُورُ وَالْأَبْوَابُ، وَانْفَضَّ الْأَهْلُ وَالْأَحْبَابُ، فَإِذَا الْوَحْشَةُ وَالْوَحْدَةُ وَهَوْلُ الْحِسَابِ.\nاللَّهُمَّ ارْحَمْنَا إِذَا فَارَقْنَا النَّعِيمَ، وَانْقَطَعَ النَّسِيمُ، وَقِيلَ مَا غَرَّكَ بِرَبِّكَ الْكَرِيمِ.\nاللَّهُمَّ ارْحَمْنَا إِذَا أُقِمْنَا لِلسُّؤَالِ، وَخَانَنَا الْمَقَالُ، وَلَمْ يَنْفَعْ جَاهٌ وَلَا مَالٌ وَلَا عِيَالٌ، وَقَدْ حَالَ الْحَالُ، وَلَيْسَ إِلَّا فَضْلُ الْكَبِيرِ الْمُتَعَالِ.\nاللَّهُمَّ ارْحَمْنَا إِذَا نُسِيَ اسْمُنَا، وَدَرَسَ رَسْمُنَا، وَأَحَاطَ بِنَا قِسْمُنَا وَوُسْعُنَا.\nاللَّهُمَّ ارْحَمْنَا إِذَا أُهْمِلْنَا فَلَمْ يَزُرْنَا زَائِرٌ، وَلَمْ يَذْكُرْنَا ذَاكِرٌ، وَمَا لَنَا مِنْ قُوَّةٍ وَلَا نَاصِرٍ، فَلَا أَمَلَ إِلَّا فِي الْقَاهِرِ الْقَادِرِ الْغَافِرِ، يَا مَنْ إِذَا وَعَدَ أَوْفَى، وَإِذَا تَوَعَّدَ عَفَا، وَشَفِّعْ يَا رَبِّ فِينَا حَبِيبَنَا الْمُصْطَفَى، وَاجْعَلْنَا مِمَّنْ صَفَا وَوَفَى، وَبِاللَّهِ اكْتَفَى، يَا أَرْحَمَ الرَّاحِمِينَ، يَا حَيُّ يَا قَيُّومُ، يَا بَدِيعَ السَّمَاوَاتِ وَالْأَرْضِ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ.\nاللَّهُمَّ إِنَّهُ عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ مَاتَ وَهُوَ يَشْهَدُ لَكَ بِالْوَحْدَانِيَّةِ وَلِرَسُولِكَ بِالشَّهَادَةِ فَاغْفِرْ لَهُ إِنَّكَ أَنْتَ الْغَفَّارُ.\nاللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُ، وَلَا تَفْتِنَّا بَعْدَهُ، وَاغْفِرْ لَنَا وَلَهُ، وَاجْمَعْنَا مَعَهُ فِي جَنَّاتِ النَّعِيمِ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ أَنْزِلْ عَلَى أَهْلِهِ الصَّبْرَ وَالسُّلْوَانَ وَأَرْضِهِمْ بِقَضَائِكَ.\nاللَّهُمَّ ثَبِّتْنَا عَلَى الْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا، وَفِي الْآخِرَةِ، وَيَوْمَ يَقُومُ الْأَشْهَادُ.\nاللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى سَيِّدِنَا مُحَمَّدٍ، وَعَلَى آلِهِ وَصَحْبِهِ وَسَلِّمْ إِلَى يَوْمِ الدِّينِ.","c":1,"h":"أَدْعِيَةٌ لِلْمُتَوَفَّى (ذُكُورٌ)","s":"أدعية عامة","f":"gen","w":"أدعية عامة جمعها الموقع — بعضها مأثور وأكثرها غير مأثور بلفظه"},{"t":"اللَّهُمَّ أَبْدِلْهَا دَارًا خَيْرًا مِنْ دَارِهَا، وَأَهْلًا خَيْرًا مِنْ أَهْلِهَا، وَأَدْخِلْهَا الْجَنَّةَ، وَأَعِذْهَا مِنْ عَذَابِ الْقَبْرِ وَمِنْ عَذَابِ النَّارِ.\nاللَّهُمَّ عَامِلْهَا بِمَا أَنْتَ أَهْلُهُ، وَلَا تُعَامِلْهَا بِمَا هِيَ أَهْلُهُ.\nاللَّهُمَّ اجْزِهَا عَنِ الْإِحْسَانِ إِحْسَانًا وَعَنِ الْإِسَاءَةِ عَفْوًا وَغُفْرَانًا.\nاللَّهُمَّ إِنْ كَانَتْ مُحْسِنَةً فَزِدْ مِنْ حَسَنَاتِهَا، وَإِنْ كَانَتْ مُسِيئَةً فَتَجَاوَزْ عَنْ سَيِّئَاتِهَا.\nاللَّهُمَّ أَدْخِلْهَا الْجَنَّةَ مِنْ غَيْرِ مُنَاقَشَةِ حِسَابٍ وَلَا سَابِقَةِ عَذَابٍ.\nاللَّهُمَّ آنِسْهَا فِي وَحْدَتِهَا وَفِي وَحْشَتِهَا وَفِي غُرْبَتِهَا.\nاللَّهُمَّ أَنْزِلْهَا مُنْزَلًا مُبَارَكًا وَأَنْتَ خَيْرُ الْمُنْزِلِينَ.\nاللَّهُمَّ أَنْزِلْهَا مَنَازِلَ الصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ، وَحَسُنَ أُولَئِكَ رَفِيقًا.\nاللَّهُمَّ اجْعَلْ قَبْرَهَا رَوْضَةً مِنْ رِيَاضِ الْجَنَّةِ، وَلَا تَجْعَلْهُ حُفْرَةً مِنْ حُفَرِ النَّارِ.\nاللَّهُمَّ افْسَحْ لَهَا فِي قَبْرِهَا مَدَّ بَصَرِهَا، وَافْرُشْ قَبْرَهَا مِنْ فِرَاشِ الْجَنَّةِ.\nاللَّهُمَّ أَعِذْهَا مِنْ عَذَابِ الْقَبْرِ، وَجَفَافِ الْأَرْضِ عَنْ جَنْبَيْهَا.\nاللَّهُمَّ امْلَأْ قَبْرَهَا بِالرِّضَا وَالنُّورِ وَالْفُسْحَةِ وَالسُّرُورِ.\nاللَّهُمَّ إِنَّهَا فِي ذِمَّتِكَ وَحَبْلِ جِوَارِكَ، فَقِهَا فِتْنَةَ الْقَبْرِ، وَعَذَابَ النَّارِ، وَأَنْتَ أَهْلُ الْوَفَاءِ وَالْحَقِّ، فَاغْفِرْ لَهَا وَارْحَمْهَا إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ.\nاللَّهُمَّ إِنَّهَا أَمَتُكَ وَبِنْتُ أَمَتِكَ خَرَجَتْ مِنَ الدُّنْيَا وَسَعَتِهَا وَمَحْبُوبِيهَا وَأَحِبَّائِهَا فِيهَا إِلَى ظُلْمَةِ الْقَبْرِ وَمَا هِيَ لَاقِيَتُهُ.\nاللَّهُمَّ إِنَّهَا كَانَتْ تَشْهَدُ أَنَّكَ لَا إِلَهَ إِلَّا أَنْتَ وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ وَأَنْتَ أَعْلَمُ بِهَا.\nاللَّهُمَّ إِنَّا نَتَوَسَّلُ بِكَ إِلَيْكَ، وَنُقْسِمُ بِكَ عَلَيْكَ أَنْ تَرْحَمَهَا وَلَا تُعَذِّبَهَا، وَأَنْ تُثَبِّتَهَا عِنْدَ السُّؤَالِ.\nاللَّهُمَّ إِنَّهَا نَزَلَتْ بِكَ وَأَنْتَ خَيْرُ مَنْزُولٍ بِهِ، وَأَصْبَحَتْ فَقِيرَةً إِلَى رَحْمَتِكَ وَأَنْتَ غَنِيٌّ عَنْ عَذَابِهَا.\nاللَّهُمَّ آتِهَا بِرَحْمَتِكَ وَرِضَاكَ، وَقِهَا فِتْنَةَ الْقَبْرِ وَعَذَابَهُ، وَآتِهَا بِرَحْمَتِكَ الْأَمْنَ مِنْ عَذَابِكَ حَتَّى تَبْعَثَهَا إِلَى جَنَّتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ انْقُلْهَا مِنْ مَوَاطِنِ الدُّودِ وَضِيقِ اللُّحُودِ إِلَى جَنَّاتِ الْخُلُودِ.\nاللَّهُمَّ احْمِهَا تَحْتَ الْأَرْضِ، وَاسْتُرْهَا يَوْمَ الْعَرْضِ، وَلَا تُخْزِهَا يَوْمَ يُبْعَثُونَ “يَوْمَ لَا يَنْفَعُ مَالٌ وَلَا بَنُونَ إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ”.\nاللَّهُمَّ يَمِّنْ كِتَابَهَا، وَيَسِّرْ حِسَابَهَا، وَثَقِّلْ بِالْحَسَنَاتِ مِيزَانَهَا، وَثَبِّتْ عَلَى الصِّرَاطِ أَقْدَامَهَا، وَأَسْكِنْهَا فِي أَعْلَى الْجَنَّاتِ بِجِوَارِ حَبِيبِكَ وَمُصْطَفَاكَ (صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ).\nاللَّهُمَّ أَمِّنْهَا مِنْ فَزَعِ يَوْمِ الْقِيَامَةِ، وَمِنْ هَوْلِ يَوْمِ الْقِيَامَةِ، وَاجْعَلْ نَفْسَهَا آمِنَةً مُطْمَئِنَّةً، وَلَقِّنْهَا حُجَّتَهَا.\nاللَّهُمَّ اجْعَلْهَا فِي بَطْنِ الْقَبْرِ مُطْمَئِنَّةً وَعِنْدَ قِيَامِ الْأَشْهَادِ آمِنَةً، وَبِجُودِ رِضْوَانِكَ وَاثِقَةً، وَإِلَى أَعْلَى دَرَجَاتِكَ سَابِقَةً.\nاللَّهُمَّ اجْعَلْ عَنْ يَمِينِهَا نُورًا حَتَّى تَبْعَثَهَا آمِنَةً مُطْمَئِنَّةً فِي نُورٍ مِنْ نُورِكَ.\nاللَّهُمَّ انْظُرْ إِلَيْهَا نَظْرَةَ رِضًا، فَإِنَّ مَنْ تَنْظُرُ إِلَيْهِ نَظْرَةَ رِضًا لَا تُعَذِّبُهُ أَبَدًا.\nاللَّهُمَّ أَسْكِنْهَا فَسِيحَ الْجِنَانِ، وَاغْفِرْ لَهَا يَا رَحْمَنُ، وَارْحَمْهَا يَا رَحِيمُ، وَتَجَاوَزْ عَمَّا تَعْلَمُ يَا عَلِيمُ.\nاللَّهُمَّ اعْفُ عَنْهَا فَإِنَّكَ الْقَائِلُ “وَيَعْفُو عَنْ كَثِيرٍ”.\nاللَّهُمَّ إِنَّهَا جَاءَتْ بِبَابِكَ، وَأَنَاخَتْ بِجَنَابِكَ، فَجُدْ عَلَيْهَا بِعَفْوِكَ وَإِكْرَامِكَ وَجُودِ إِحْسَانِكَ.\nاللَّهُمَّ إِنَّ رَحْمَتَكَ وَسِعَتْ كُلَّ شَيْءٍ فَارْحَمْهَا رَحْمَةً تَطْمَئِنُّ بِهَا نَفْسُهَا، وَتَقَرُّ بِهَا عَيْنُهَا.\nاللَّهُمَّ احْشُرْهَا مَعَ الْمُتَّقِينَ إِلَى الرَّحْمَنِ وَفْدًا.\nاللَّهُمَّ احْشُرْهَا مَعَ أَصْحَابِ الْيَمِينِ، وَاجْعَلْ تَحِيَّتَهَا سَلَامٌ لَكَ مِنْ أَصْحَابِ الْيَمِينِ.\nاللَّهُمَّ بَشِّرْهَا بِقَوْلِكَ “كُلُوا وَاشْرَبُوا هَنِيئًا بِمَا أَسْلَفْتُمْ فِي الْأَيَّامِ الْخَالِيَةِ”\nاللَّهُمَّ اجْعَلْهَا مِنَ الَّذِينَ سُعِدُوا فِي الْجَنَّةِ خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ.\nاللَّهُمَّ لَا نُزَكِّيهَا عَلَيْكَ، وَلَكِنَّا نَحْسَبُهَا أَنَّهَا آمَنَتْ وَعَمِلَتْ صَالِحًا، فَاجْعَلْ لَهَا جَنَّتَيْنِ ذَوَاتَيْ أَفْنَانٍ بِحَقِّ قَوْلِكَ: “وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ”.\nاللَّهُمَّ شَفِّعْ فِيهَا نَبِيَّنَا وَمُصْطَفَاكَ، وَاحْشُرْهَا تَحْتَ لِوَائِهِ، وَاسْقِهَا مِنْ يَدِهِ الشَّرِيفَةِ شَرْبَةً هَنِيئَةً لَا تَظْمَأُ بَعْدَهَا أَبَدًا.\nاللَّهُمَّ اجْعَلْهَا فِي جَنَّةِ الْخُلْدِ \"الَّتِي وُعِدَ الْمُتَّقُونَ كَانَتْ لَهُمْ جَزَاءً وَمَصِيرًا. لَهُمْ فِيهَا مَا يَشَاءُونَ خَالِدِينَ كَانَ عَلَى رَبِّكَ وَعْدًا مَسْؤُولًا\".\nاللَّهُمَّ إِنَّهَا صَبَرَتْ عَلَى الْبَلَاءِ فَلَمْ تَجْزَعْ، فَامْنَحْهَا دَرَجَةَ الصَّابِرِينَ الَّذِينَ يُوَفَّوْنَ أُجُورَهُمْ بِغَيْرِ حِسَابٍ فَإِنَّكَ الْقَائِلُ \"إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ\".\nاللَّهُمَّ إِنَّهَا كَانَتْ تُصَلِّي لَكَ، فَثَبِّتْهَا عَلَى الصِّرَاطِ يَوْمَ تَزِلُّ الْأَقْدَامُ.\nاللَّهُمَّ إِنَّهَا كَانَتْ صَائِمَةً لَكَ، فَأَدْخِلْهَا الْجَنَّةَ مِنْ بَابِ الرَّيَّانِ.\nاللَّهُمَّ إِنَّهَا كَانَتْ لِكِتَابِكَ تَالِيَةً وَسَامِعَةً، فَشَفِّعْ فِيهَا الْقُرْآنَ، وَارْحَمْهَا مِنَ النِّيرَانِ، وَاجْعَلْهَا يَا رَحْمَنُ تَرْتَقِي فِي الْجَنَّةِ إِلَى آخِرِ آيَةٍ قَرَأَتْهَا أَوْ سَمِعَتْهَا، وَآخِرِ حَرْفٍ تَلَتْهُ.\nاللَّهُمَّ ارْزُقْهَا بِكُلِّ حَرْفٍ فِي الْقُرْآنِ حَلَاوَةً، وَبِكُلِّ كَلِمَةٍ كَرَامَةً، وَبِكُلِّ آيَةٍ سَعَادَةً، وَبِكُلِّ سُورَةٍ سَلَامَةً، وَبِكُلِّ جُزْءٍ جَزَاءً.\nاللَّهُمَّ ارْحَمْهَا فَإِنَّهَا كَانَتْ مُسْلِمَةً، وَاغْفِرْ لَهَا فَإِنَّهَا كَانَتْ مُؤْمِنَةً، وَأَدْخِلْهَا الْجَنَّةَ فَإِنَّهَا كَانَتْ بِنَبِيِّكَ مُصَدِّقَةً، وَسَامِحْهَا فَإِنَّهَا كَانَتْ لِكِتَابِكَ مُرَتِّلَةً.\nاللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبِيرِنَا، وَذَكَرِنَا وَأُنْثَانَا.\nاللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلَامِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِيمَانِ.\nاللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهَا وَلَا تُضْلِلْنَا بَعْدَهَا.\nاللَّهُمَّ ارْحَمْنَا إِذَا أَتَانَا الْيَقِينُ، وَعَرِقَ مِنَّا الْجَبِينُ، وَكَثُرَ الْأَنِينُ وَالْحَنِينُ.\nاللَّهُمَّ ارْحَمْنَا إِذَا يَئِسَ مِنَّا الطَّبِيبُ، وَبَكَى عَلَيْنَا الْحَبِيبُ، وَتَخَلَّى عَنَّا الْقَرِيبُ وَالْغَرِيبُ، وَارْتَفَعَ النَّشِيجُ وَالنَّحِيبُ.\nاللَّهُمَّ ارْحَمْنَا إِذَا اشْتَدَّتِ الْكُرُبَاتُ، وَتَوَالَتِ الْحَسَرَاتُ، وَأَطْبَقَتِ الرَّوْعَاتُ، وَفَاضَتِ الْعَبَرَاتُ، وَتَكَشَّفَتِ الْعَوْرَاتُ، وَتَعَطَّلَتِ الْقُوَى وَالْقُدُرَاتُ.\nاللَّهُمَّ ارْحَمْنَا إِذَا حُمِلْنَا عَلَى الْأَعْنَاقِ، وَبَلَغَتِ التَّرَاقِيَ، وَقِيلَ مَنْ رَاقٍ وَظَنَّ أَنَّهُ الْفِرَاقُ وَالْتَفَّتِ السَّاقُ بِالسَّاقِ، إِلَيْكَ يَا رَبَّنَا يَوْمَئِذٍ الْمَسَاقُ.\nاللَّهُمَّ ارْحَمْنَا إِذَا وُورِينَا التُّرَابَ، وَغُلِّقَتِ الْقُبُورُ وَالْأَبْوَابُ، وَانْفَضَّ الْأَهْلُ وَالْأَحْبَابُ، فَإِذَا الْوَحْشَةُ وَالْوَحْدَةُ وَهَوْلُ الْحِسَابِ.\nاللَّهُمَّ ارْحَمْنَا إِذَا فَارَقْنَا النَّعِيمَ، وَانْقَطَعَ النَّسِيمُ، وَقِيلَ مَا غَرَّكَ بِرَبِّكَ الْكَرِيمِ.\nاللَّهُمَّ ارْحَمْنَا إِذَا أُقِمْنَا لِلسُّؤَالِ، وَخَانَنَا الْمَقَالُ، وَلَمْ يَنْفَعْ جَاهٌ وَلَا مَالٌ وَلَا عِيَالٌ، وَقَدْ حَالَ الْحَالُ، وَلَيْسَ إِلَّا فَضْلُ الْكَبِيرِ الْمُتَعَالِ.\nاللَّهُمَّ ارْحَمْنَا إِذَا نُسِيَ اسْمُنَا، وَدَرَسَ رَسْمُنَا، وَأَحَاطَ بِنَا قِسْمُنَا وَوُسْعُنَا.\nاللَّهُمَّ ارْحَمْنَا إِذَا أُهْمِلْنَا فَلَمْ يَزُرْنَا زَائِرٌ، وَلَمْ يَذْكُرْنَا ذَاكِرٌ، وَمَا لَنَا مِنْ قُوَّةٍ وَلَا نَاصِرٍ، فَلَا أَمَلَ إِلَّا فِي الْقَاهِرِ الْقَادِرِ الْغَافِرِ، يَا مَنْ إِذَا وَعَدَ أَوْفَى، وَإِذَا تَوَعَّدَ عَفَا، وَشَفِّعْ يَا رَبِّ فِينَا حَبِيبَنَا الْمُصْطَفَى، وَاجْعَلْنَا مِمَّنْ صَفَا وَوَفَى، وَبِاللَّهِ اكْتَفَى، يَا أَرْحَمَ الرَّاحِمِينَ، يَا حَيُّ يَا قَيُّومُ، يَا بَدِيعَ السَّمَاوَاتِ وَالْأَرْضِ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ.\nاللَّهُمَّ إِنَّهَا أَمَتُكَ بِنْتُ أَمَتِكَ مَاتَتْ وَهِيَ تَشْهَدُ لَكَ بِالْوَحْدَانِيَّةِ وَلِرَسُولِكَ بِالشَّهَادَةِ فَاغْفِرْ لَهَا إِنَّكَ أَنْتَ الْغَفَّارُ.\nاللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهَا، وَلَا تَفْتِنَّا بَعْدَهَا، وَاغْفِرْ لَنَا وَلَهَا، وَاجْمَعْنَا مَعَهَا فِي جَنَّاتِ النَّعِيمِ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ أَنْزِلْ عَلَى أَهْلِهَا الصَّبْرَ وَالسُّلْوَانَ وَأَرْضِهِمْ بِقَضَائِكَ.\nاللَّهُمَّ ثَبِّتْنَا عَلَى الْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا، وَفِي الْآخِرَةِ، وَيَوْمَ يَقُومُ الْأَشْهَادُ.\nاللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى سَيِّدِنَا مُحَمَّدٍ، وَعَلَى آلِهِ وَصَحْبِهِ وَسَلِّمْ إِلَى يَوْمِ الدِّينِ.","c":1,"h":"أَدْعِيَةٌ لِلْمُتَوَفَّاةِ (إِنَاثٌ)","s":"أدعية عامة","f":"gen","w":"أدعية عامة جمعها الموقع — بعضها مأثور وأكثرها غير مأثور بلفظه"},{"t":"اللَّهُمَّ اجْعَلْهُ فَرَطًا وَذُخْرًا لِوَالِدَيْهِ، وَشَفِيعًا مُجَابًا، اللَّهُمَّ ثَقِّلْ بِهِ مَوَازِينَهُمَا، وَأَعْظِمْ بِهِ أُجُورَهُمَا، وَأَلْحِقْهُ بِصَالِحِ الْـمُؤْمِنِينَ، وَاجْعَلْهُ فِي كَفَالَةِ إِبْرَاهِيمَ، وَقِهِ بِرَحْمَتِكَ عَذَابَ الْجَحِيمِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، اللَّهُمَّ اغْفِرْ لِأَسْلَافِنَا، وَأَفْرَاطِنَا، وَمَنْ سَبَقَنَا بِالْإِيمَانِ.","c":1,"h":"أَدْعِيَةٌ لِلْمَيِّتِ الطِّفْلِ الصَّغِيرِ (ذَكَرٍ أَوْ أُنْثَى)","s":"أدعية مأثورة عن بعض السلف","f":"gen","w":"ليست حديثًا مرفوعًا — نُقلت عن بعض السلف"},{"t":"اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ وَعَافِهِ وَاعْفُ عَنْهُ ، وَأَكْرِمْ نُزُلَهُ ، وَوَسِّعْ مُدْخَلَهُ ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ ، وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ ، وَأَدْخِلْهُ الْجَنَّةَ ، وَقِهِ فِتْنَةَ الْقَبْرِ وَعَذَابَ النَّارِ.","c":1,"h":"الدُّعَاءُ لِلْمَيِّتِ فِي صَلَاةِ الْجَنَازَةِ","s":"رواه مسلم من حديث عوف بن مالك"}]},{"k":"jawami","ar":"جوامع الدعاء","en":"Comprehensive duas","items":[{"t":"اللَّهُمَّ يَا بَارِئَ الْبَرِيَّاتِ ، وَغَافِرَ الْخَطِيئَاتِ ، وَعَالِمَ الْخَفِيَّاتِ ، الْمُطَّلِعَ عَلَى الضَّمَائِرِ وَالنِّيَّاتِ ، يَا مَنْ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا ، وَوَسِعَ كُلَّ شَيْءٍ رَحْمَةً ، وَقَهَرَ كُلَّ مَخْلُوقٍ عِزَّةً وَحُكْماً ، اغْفِرْ لِي ذُنُوبِي ، وَاسْتُرْ عُيُوبِيَ ، وَتَجَاوَزْ عَنْ سَيِّئَاتِيَ إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ.\nاللَّهُمَّ يَا سَمِيعَ الدَّعَوَاتِ ، يَا مُقِيلَ الْعَثَرَاتِ ، يَا قَاضِيَ الْحَاجَاتِ ، يَا كَاشِفَ الْكَرُبَاتِ ، يَا رَفِيعَ الدَّرَجَاتِ ، وَيَا غَافِرَ الزَّلَّاتِ ، اغْفِرْ لِلْمُسْلِمِينَ وَالْمُسْلِمَاتِ ، وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ، الْأَحْيَاءِ مِنْهُمْ وَالْأَمْوَاتِ ، إِنَّكَ سَمِيعٌ قَرِيبٌ مُجِيبُ الدَّعَوَاتِ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ بِاسْمِكَ الْأَعْظَمِ ، الَّذِي إِذَا دُعِيتَ بِهِ أَجَبْتَ ، وَإِذَا سُئِلْتَ بِهِ أَعْطَيْتَ ، أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ ، الْأَحَدُ الصَّمَدُ ، الَّذِي لَمْ يَلِدْ، وَلَمْ يُولَدْ ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ؛ أَنْ تَغْفِرَ لِي ذُنُوبِي ، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ كَرِيمٌ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي.\nاللَّهُمَّ رَبِّ اغْفِرْ لِي وَلِوَالِدَيَّ وَلِمَنْ دَخَلَ بَيْتِيَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي ، وَإِسْرَافِي فِي أَمْرِي ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي ، اللَّهُمَّ اغْفِرْ لِي هَزْلِي وَجِدِّي ، وَخَطَئِي وَعَمْدِي ، وَكُلُّ ذَلِكَ عِنْدِي.\nاللَّهُمَّ رَبِّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي.\nاللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ.\nاللَّهُمَّ اغْفِرْ لِي ، وَارْحَمْنِي وَاهْدِنِي ، وَعَافِنِي وَارْزُقْنِي ، وَاجْبُرْنِي ، وَارْفَعْنِي.\nاللَّهُمَّ يَا مَنْ لَا تَضُرُّهُ الذُّنُوبُ ، وَلَا تُنْقِصُهُ الْمَغْفِرَةُ ، اغْفِرْ لَنَا مَا لَا يَضُرُّكَ ، وَهَبْ لَنَا مَا لَا يُنْقِصُكَ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ ، دِقَّهُ وَجِلَّهُ ، وَأَوَّلَهُ وَآخِرَهُ ، وَعَلَانِيَتَهُ وَسِرَّهُ.\nاللَّهُمَّ إِنَّ ذُنُوبِي عِظَامٌ وَهِيَ صِغَارٌ فِي جَنْبِ عَفْوِكَ يَا كَرِيمُ ، فَاغْفِرْهَا لِي.\nاللَّهُمَّ اغْفِرْ لِي ذَنْبِي ، وَوَسِّعْ لِي فِي دَارِي ، وَبَارِكْ لِي فِي رِزْقِي.\nاللَّهُمَّ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا ، رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا ، رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ، وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ.\nاللَّهُمَّ إِنَّا قَدْ أَطَعْنَاكَ فِي أَحَبِّ الْأَشْيَاءِ إِلَيْكَ أَنْ تُطَاعَ فِيهِ ، الْإِيمَانِ بِكَ ، وَالْإِقْرَارِ بِكَ ، وَلَمْ نَعْصِكَ فِي أَبْغَضِ الْأَشْيَاءِ أَنْ تُعْصَى فِيهِ ؛ الْكُفْرِ وَالْجَحْدِ بِكَ ، اللَّهُمَّ فَاغْفِرْ لَنَا مَا بَيْنَهُمَا.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ ، وَمَا أَعْلَنْتُ وَمَا أَسْرَرْتُ ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي ، أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ.\nاللَّهُمَّ رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ.\nاللَّهُمَّ رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ ، رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَحْمَةً وَعِلْمًا فَاغْفِرْ لِلَّذِينَ تَابُوا وَاتَّبَعُوا سَبِيلَكَ وَقِهِمْ عَذَابَ الْجَحِيمِ.\nاللَّهُمَّ أَقِلْ عَثَرَاتِنَا ، وَاغْفِرْ زَلَّاتِنَا ، وَكَفِّرْ عَنَّا سَيِّئَاتِنَا ، وَتَوَفَّنَا مَعَ الْأَبْرَارِ.\nاللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ ، اللَّهُمَّ اغْسِلْنِي مِنْ خَطَايَايَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ ، اللَّهُمَّ نَقِّنِي مِنْ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا ، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ. فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدَكَ ، وَارْحَمْنِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ يَا اللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ ، الصَّمَدُ ، الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُواً أَحَدٌ ، أَنْ تَغْفِرَ لِي ذُنُوبِي ، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ.\nاللَّهُمَّ إِلَهِي : حُجَّتِي حَاجَتِي ، وَعُدَّتِي فَاقَتِي ، فَارْحَمْنِي.\nاللَّهُمَّ إِلَهِي : كَيْفَ أَمْتَنِعُ بِالذَّنْبِ مِنَ الدُّعَاءِ ، وَلَا أَرَاكَ تَمْنَعُ مَعَ الذَّنْبِ مِنَ الْعَطَاءِ ، فَإِنْ غَفَرْتَ فَخَيْرُ رَاحِمٍ أَنْتَ ، وَإِنْ عَذَّبْتَ فَغَيْرُ ظَالِمٍ أَنْتَ.\nاللَّهُمَّ إِلَهِي: أَسْأَلُكَ تَذَلُّلاً فَأَعْطِنِي تَفَضُّلاً.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ يَا مَنْ عَلَى الْعَرْشِ اسْتَوَى ، يَا مَنْ خَلَقَ فَسَوَّى وَقَدَّرَ فَهَدَى ، وَأَعْطَى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَى ، يَا مَنْ أَضْحَكَ وَأَبْكَى، وَأَمَاتَ وَأَحْيَا ، وَأَسْعَدَ وَأَشْقَى ، وَأَوْجَدَ وَأَبْلَى ، وَرَفَعَ وَخَفَضَ ، وَأَعَزَّ وَأَذَلَّ، وَأَعْطَى وَمَنَعَ ، وَرَفَعَ وَوَضَعَ.\nاللَّهُمَّ يَا مَنْ شَقَّ الْبِحَارَ ، وَأَجْرَى الْأَنْهَارَ ، وَكَوَّرَ النَّهَارَ عَلَى اللَّيْلِ وَاللَّيْلَ عَلَى النَّهَارِ ، يَا مَنْ هَدَى مِنْ ضَلَالَةٍ ، وَأَنْقَذَ مِنْ جَهَالَةٍ ، وَأَنَارَ الْأَبْصَارَ ، وَأَحْيَا الضَّمَائِرَ وَالْأَفْكَارَ.\nاللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ ، وَعَافِنَا فِيمَنْ عَافَيْتَ ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ.\nاللَّهُمَّ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ، صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ.\nاللَّهُمَّ وَفِّقْنَا لِهُدَاكَ وَاجْعَلْ عَمَلَنَا فِي رِضَاكَ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ أَرِنَا الْحَقَّ حَقًّا وَارْزُقْنَا اتِّبَاعَهُ، وَأَرِنَا الْبَاطِلَ بَاطِلاً وَارْزُقْنَا اجْتِنَابَهُ.\nاللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا ، وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا.\nاللَّهُمَّ رَبَّنَا أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.\nاللَّهُمَّ حَبِّبْ إِلَيْنَا الْإِيمَانَ وَزَيِّنْهُ فِي قُلُوبِنَا ، وَكَرِّهِ إِلَيْنَا الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ ، وَاجْعَلْنَا مِنَ الرَّاشِدِينَ.\nاللَّهُمَّ مُصَرِّفَ الْقُلُوبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ خُذْ بِنَوَاصِينَا لِلْبِرِّ وَالتَّقْوَى ، وَلِمَا تُحِبُّ مِنَ الْعَمَلِ وَتَرْضَى.\nاللَّهُمَّ رَبَّ جِبْرَائِيلَ وَمِيكَائِيلَ ، وَإِسْرَافِيلَ ، فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ ، اهْدِنَا لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ ، إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ.\nاللَّهُمَّ إِنِّي عَبْدُكَ ابْنُ عَبْدِكَ ابْنُ أَمَتِكَ ، نَاصِيَتِي بِيَدِكَ ، مَاضٍ فِيَّ حُكْمُكَ ، عَدْلٌ فِيَّ قَضَاؤُكَ ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ ، سَمَّيْتَ بِهِ نَفْسَكَ ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ ، أَوْ عَلَّمْتَهُ أَحَداً مِنْ خَلْقِكَ ، أَوْ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي ، وَنُورَ صَدْرِي ، وَجَلَاءَ حَزَنِي ، وَذَهَابَ هَمِّي.\nاللَّهُمَّ اجْعَلْ فِي قَلْبِي نُوراً ، وَفِي سَمْعِي نُوراً ، وَفِي بَصَرِي نُوراً ، وَعَنْ يَمِينِي نُوراً ، وَعَنْ شِمَالِي نُوراً ، وَمِنْ بَيْنَ يَدَيَّ نُوراً ، وَمِنْ خَلْفِي نُوراً ، وَمِنْ فَوْقِي نُوراً ، وَمِنْ تَحْتِي نُوراً ، وَاجْعَلْ لِي نُوراً ، وَأَعْظِمْ لِي نُوراً.\nاللَّهُمَّ أَغْنِنِي بِالْعِلْمِ ، وَزَيِّنِّي بِالْحِلْمِ ، وَأَكْرِمْنِي بِالتَّقْوَى ، وَجَمِّلْنِي بِالْعَافِيَةِ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمَ الْخَائِفِينَ مِنْكَ ، وَخَوْفَ الْعَالِمِينَ بِكَ ، وَيَقِينَ الْمُتَوَكِّلِينَ عَلَيْكَ ، وَتَوَكُّلَ الْمُوقِنِينَ بِكَ ، وَإِنَابَةَ الْمُخْبِتِينَ إِلَيْكَ ، وَإِخْبَاتَ الْمُنِيبِينَ إِلَيْكَ ، وَشُكْرَ الصَّابِرِينَ لَكَ ، وَصَبْرَ الشَّاكِرِينَ لَكَ ، وَلَحَاقاً بِالْأَحْيَاءِ الْمَرْزُوقِينَ عِنْدَكَ.\nاللَّهُمَّ اهْدِنِي وَسَدِّدْنِي ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالسَّدَادَ.\nاللَّهُمَّ أَلْهِمْنِي رُشْدِي ، وَأَعِذْنِي مِنْ شَرِّ نَفْسِي.\nاللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي ، وَعَلِّمْنِي مَا يَنْفَعُنِي ، وَزِدْنِي عِلْماً.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نَافِعاً ، وَأَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ ثَبِّتْنِي وَاجْعَلْنِي هَادِياً مَهْدِيّاً.\nاللَّهُمَّ لَكَ أَسْلَمْتُ ، وَبِكَ آمَنْتُ ، وَعَلَيْكَ تَوَكَّلْتُ ، وَإِلَيْكَ أَنَبْتُ ، وَبِكَ خَاصَمْتُ، أَعُوذُ بِعِزَّتِكَ ، لَا إِلَهَ إِلَّا أَنْتَ ، أَنْ تُضِلَّنِي ، أَنْتَ الْحَيُّ الَّذِي لَا يَمُوتُ ، وَالْجِنُّ وَالْإِنْسُ يَمُوتُونَ.\nاللَّهُمَّ اهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ ، وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ.\nاللَّهُمَّ كَمَا أَحْسَنْتَ خَلْقِي فَأَحْسِنْ خُلُقِي.\nاللَّهُمَّ فَالِقَ الْحَبِّ وَالنَّوَى ، وَمُخْرِجَ الْحَيِّ مِنَ الْمَيِّتِ وَمُخْرِجَ الْمَيِّتِ مِنَ الْحَيِّ ، فَالِقَ الْإِصْبَاحِ ، وَجَاعِلَ اللَّيْلِ سَكَنًا ، وَالشَّمْسَ وَالْقَمَرَ حُسْبَاناً ، يَا مَنْ جَعَلَ لَنَا النُّجُومَ لِنَهْتَدِيَ بِهَا فِي ظُلُمَاتِ الْبَرِّ وَالْبَحْرِ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ جَلَّتْ قُدْرَتُكَ ، وَتَعَالَتْ حِكْمَتُكَ ، وَتَبَارَكَ اسْمُكَ ، وَتَعَالَى جَدُّكَ ، وَلَا إِلَهَ غَيْرُكَ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ ، لَا إِلَهَ إِلَّا أَنْتَ ، الْمَنَّانُ ، بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ، ذُو الْجَلَالِ وَالْإِكْرَامِ ، يَا حَيُّ يَا قَيُّومُ.\nاللَّهُمَّ ارْزُقْنَا رِزْقًا يَزِيدُنَا لَكَ شُكْراً ، وَإِلَيْكَ فَاقَةً وَفَقْراً ، وَبِكَ عَمَّنْ سِوَاكَ غِنًى.\nاللَّهُمَّ اجْعَلْ أَوْسَعَ رِزْقِكَ عَلَيَّ عِنْدَ كِبَرِ سِنِّي ، وَانْقِطَاعِ عُمُرِي.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ وَرَحْمَتِكَ فَإِنَّهُ لَا يَمْلِكُهَا إِلَّا أَنْتَ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ رَبِّ لَا تَذَرْنِي فَرْداً وَأَنْتَ خَيْرُ الْوَارِثِينَ.\nاللَّهُمَّ رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ.\nاللَّهُمَّ قَنِّعْنِي بِمَا رَزَقْتَنِي ، وَبَارِكْ لِي فِيهِ ، وَاخْلُفْ عَلَيَّ كُلَّ غَائِبَةٍ لِي مِنْكَ بِخَيْرٍ.\nاللَّهُمَّ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَاماً.\nاللَّهُمَّ يَا مَنْ تُسَبِّحُ لَهُ السَّمَاوَاتُ بِنُجُومِهَا وَأَبْرَاجِهَا ، وَالْأَرْضُ بِسُهُولِهَا وَفِجَاجِهَا ، وَالْبِحَارُ بِأَحْيَائِهَا وَأَمْوَاجِهَا ، وَالْجِبَالُ بِقِمَمِهَا وَأَوْتَادِهَا ، وَالْأَشْجَارُ بِفُرُوعِهَا وَثِمَارِهَا ، وَالسِّبَاعُ فِي فَلَوَاتِهَا ، وَالطَّيْرُ فِي وَكَنَاتِهَا ، يَا مَنْ تُسَبِّحُ لَهُ الذَّرَّاتُ عَلَى صِغَرِهَا ، وَالْمَجَرَّاتُ عَلَى كِبَرِهَا ، يَا مَنْ تُسَبِّحُ لَهُ السَّمَاوَاتُ السَّبْعُ وَالْأَرْضُ وَمَنْ فِيهِنَّ ، وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ يَا مَنْ خَلَقَ الْأَرْضَ وَالسَّمَاوَاتِ الْعُلَى ، يَا رَحْمَاناً عَلَى الْعَرْشِ اسْتَوَى ، يَا مَنْ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَمَا بَيْنَهُمَا ، وَمَا تَحْتَ الثَّرَى ، يَا مَنْ يَعْلَمُ السِّرَ وَأَخْفَى، يَا مَنْ لَهُ الْأَسْمَاءُ الْحُسْنَى ، يَا مَنْ مَعَ عِبَادِهِ يَسْمَعُ وَيَرَى ، يَا مَنْ أَعْطَى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَى.\nاللَّهُمَّ أَنْتَ الْبَادِئُ بِالْإِحْسَانِ مِنْ قَبْلِ تَوَجُّهِ الْعَابِدِينَ ، وَأَنْتَ الْبَادِئُ بِالْعَطَايَا قَبْلَ طَلَبِ الطَّالِبِينَ وَأَنْتَ الْوَهَّابُ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ وَعَمَلٍ ، وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ وَعَمَلٍ.\nاللَّهُمَّ رَبِّ ابْنِ لِي عِنْدَكَ بَيْتاً فِي الْجَنَّةِ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ رِضَاكَ وَالْجَنَّةَ ، وَأَعُوذُ بِكَ مِنْ سَخَطِكَ وَالنَّارِ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُورِ كُلِّهَا ، وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآخِرَةِ.\nاللَّهُمَّ رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا كَانَ غَرَاماً.\nاللَّهُمَّ رَبَّنَا إِنَّنَا آمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ ، وَأَسْتَجِيرُ بِكَ مِنَ النَّارِ.\nاللَّهُمَّ رَبَّنَا وَآتِنَا مَا وَعَدْتَنَا عَلَى رُسِلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ حَاسِبْنِي حِسَاباً يَسِيراً.\nاللَّهُمَّ إِنَّا نَعُوذُ بِكَ أَنْ نُشْرِكَ بِكَ شَيْئاً نَعْلَمُهُ ، وَنَسْتَغْفِرُكَ لِمَا لَا نَعْلَمُهُ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَهْدِ الْبَلَاءِ ، وَدَرَكِ الشَّقَاءِ ، وَسُوءِ الْقَضَاءِ ، وَشَمَاتَةِ الْأَعْدَاءِ ، يَا سَمِيعَ الدُّعَاءِ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ ، وَمِنْ عَذَابِ الْقَبْرِ ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ ، وَمِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ ، وَأَعُوذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ النَّارِ وَعَذَابِ النَّارِ ، وَفِتْنَةِ الْقَبْرِ ، وَعَذَابِ الْقَبْرِ ، وَشَرِّ فِتْنَةِ الْغِنَى ، وَشَرِّ فِتْنَةِ الْفَقْرِ ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ اغْسِلْ قَلْبِي بِمَاءِ الثَّلْجِ وَالْبَرَدِ ، وَنَقِّ قَلْبِيَ مِنْ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ ، وَبَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكَسَلِ وَالْمَأْثَمِ وَالْمَغْرَمِ.\nاللَّهُمَّ رَبَّ جِبْرَائِيلَ ، وَمِيكَائِيلَ ، وَرَبَّ إِسْرَافِيلَ ، أَعُوذُ بِكَ مِنْ حَرِّ النَّارِ وَمِنْ عَذَابِ الْقَبْرِ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَارِ السُّوءِ فِي دَارِ الْمُقَامَةِ ، فَإِنَّ جَارَ الْبَادِيَةِ يَتَحَوَّلُ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ ، وَالْجُبْنِ وَالْبُخْلِ ، وَالْهَرَمِ وَالْقَسْوَةِ ، وَالْغَفْلَةِ وَالْعَيْلَةِ وَالذِّلَّةِ ، وَالْمَسْكَنَةِ ، وَأَعُوذُ بِكَ مِنَ الْفَقْرِ وَالْكُفْرِ ، وَالْفُسُوقِ وَالشِّقَاقِ وَالنِّفَاقِ، وَالسُّمْعَةِ وَالرِّيَاءِ ، وَأَعُوذُ بِكَ مِنَ الصَّمَمِ وَالْبَكَمِ ، وَالْجُنُونِ ، وَالْجِذَامِ ، وَالْبَرَصِ ، وَسَيِّئِ الْأَسْقَامِ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ ، وَالْجُبْنِ ، وَالْبُخْلِ ، وَالْهَرَمِ ، وَعَذَابِ الْقَبْرِ، اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا ، وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا ، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ ، وَمِنْ قَلْبٍ لَا يَخْشَعُ ، وَمِنْ نَفْسٍ لَا تَشْبَعُ ، وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مُنْكَرَاتِ الْأَخْلَاقِ وَالْأَعْمَالِ وَالْأَهْوَاءِ وَالْأَدْوَاءِ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ تُحَسِّنَ فِي لَوَائِحِ الْعُيُونِ عَلَانِيَتِي ، وَتُقَبِّحَ فِي خَفِيَّاتِ الْعُيُونِ سَرِيرَتِي ، اللَّهُمَّ كَمَا أَسَأْتُ وَأَحْسَنْتَ إِلَيَّ ، فَإِذَا عُدْتُ فَعُدْ عَلَيَّ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ سَمْعِي ، وَمِنْ شَرِّ بَصَرِي ، وَمِنْ شَرِّ لِسَانِي ، وَمِنْ شَرِّ قَلْبِي ، وَمِنْ شَرِّ مَنِيِّي.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَقُولَ زُوراً ، أَوْ أَغْشَى فُجُوراً ، أَوْ أَكُونَ بِكَ مَغْرُوراً.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الشِّقَاقِ وَالنِّفَاقِ ، وَسُوءِ الْأَخْلَاقِ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ ، وَبِكَ مِنْكَ ، لَا أُحْصِي ثَنَاءً عَلَيْكَ ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ.\nاللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَرَبَّ الْأَرْضِ ، وَرَبَّ الْعَرْشِ الْعَظِيمِ ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ ، فَالِقَ الْحَبِّ وَالنَّوَى ، وَمُنَزِّلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْفُرْقَانَ ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ ، اللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيءٌ ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيءٌ ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيءٌ ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ ، وَغَلَبَةِ الْعَدُوِّ ، وَشَمَاتَةِ الْأَعْدَاءِ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْفَقْرِ وَالْقِلَّةِ وَالذِّلَّةِ ، وَأَعُوذُ بِكَ مِنْ أَنْ أَظْلِمَ أَوْ أُظْلَمَ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ فِتْنَةِ الْغِنَى ، وَمِنْ شَرِّ فِتْنَةِ الْفَقْرِ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ ، وَتَحَوُّلِ عَافِيَتِكَ ، وَفُجَاءَةِ نِقْمَتِكَ ، وَجَمِيعِ سَخَطِكَ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ يَوْمِ السُّوءِ ، وَمِنْ لَيْلَةِ السُّوءِ ، وَمِنْ سَاعَةِ السُّوءِ ، وَمِنْ صَاحِبِ السُّوءِ ، وَمِنْ جَارِ السُّوءِ ، فِي دَارِ الْمُقَامَةِ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ قَلْبٍ لَا يَخْشَعُ ، وَمِنْ دُعَاءٍ لَا يُسْمَعُ ، وَمِنْ نَفْسٍ لَا تَشْبَعُ ، وَمِنْ عِلْمٍ لَا يَنْفَعُ ، أَعُوذُ بِكَ مِنْ هَؤُلَاءِ الْأَرْبَعِ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ التَّرَدِّي ، وَالْهَدْمِ ، وَالْغَرَقِ ، وَالْحَرْقِ وَأَعُوذُ بِكَ أَنْ يَتَخَبَّطَنِي الشَّيْطَانُ عِنْدَ الْمَوْتِ ، وَأَعُوذُ بِكَ مِنْ أَنْ أَمُوتَ فِي سَبِيلِكَ مُدْبِراً ، وَأَعُوذُ بِكَ أَنْ أَمُوتَ لَدِيغاً.\nاللَّهُمَّ رَبِّ أَعُوذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ ، وَأَعُوذُ بِكَ رَبِّ أَنْ يَحْضُرُونَ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ الْأَشْرَارِ ، وَمِنْ كَيْدِ الْفُجَّارِ ، ومِنْ طَوَارِقِ اللَّيْلِ وَالنَّهَارِ إِلَّا طَارِقًا يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ.\nاللَّهُمَّ رَبِّ أَعُوذُ بِكَ مِنْ أَعْيُنِ الْعَائِنِينَ ، وَمِنْ سِحْرِ السَّاحِرِينَ ، وَمِنْ شَرِّ كُلِّ ذِي شَرٍّ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُوعِ ، فَإِنَّهُ بِئْسَ الضَّجِيعُ ، وَأَعُوذُ بِكَ مِنْ الْخِيَانَةِ ، فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عُقُوقِ الْأَبْنَاءِ ، وَمِنْ قَطِيعَةِ الْأَقْرِبَاءِ ، وَمِنْ جَفْوَةِ الْأَحْيَاءِ ، وَمِنْ تَغَيُّرِ الْأَصْدِقَاءِ ، وَمِنْ شَمَاتَةِ الْأَعْدَاءِ.\nاللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ أَنْ أَزِلَّ أَوْ أُزَلَّ ، أَوْ أَضِلَّ أَوْ أُضَلَّ ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ.\nاللَّهُمَّ إِنَّا نَسْتَعِينُكَ وَنَسْتَهْدِيكَ، وَنَسْتَغْفِرُكَ وَنَتُوبُ إِلَيْكَ وَنُؤْمِنُ بِكَ ، وَنَتَوَكَّلُ عَلَيْكَ ، وَنُثْنِي عَلَيْكَ الْخَيْرَ كُلَّهُ ، نَشْكُرُكَ وَلَا نَكْفُرُكَ ، وَنَخْلَعُ وَنَتْرُكُ مَنْ يَفْجُرُكَ ، اللَّهُمَّ إِيَّاكَ نَعْبُدُ ، وَلَكَ نُصَلِّي وَنَسْجُدُ ، وَإِلَيكَ نَسْعَى وَنَحْفِدُ ، نَرْجُو رَحْمَتَكَ ، وَنَخْشَى عَذَابَكَ ، إِنَّ عَذَابَكَ الْجِدَّ بِالْكُفَّارِ مُلْحِقٌ.\nاللَّهُمَّ رَبَّنَا أَعِزَّنَا بِالْإِسْلَامِ ، وَأَعِزَّ بِنَا الْإِسْلَامَ ، اللَّهُمَّ أَعْلِ بِنَا كَلِمَةَ الْإِسْلَامِ ، وَارْفَعْ بِنَا رَايَةَ الْقُرْآنِ.\nاللَّهُمَّ مُنْزِلَ الْكِتَابِ ، وَمُجْرِيَ السَّحَابِ وَهَازِمَ الْأَحْزَابِ ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ أَسْأَلُكَ بِاسْمِكَ الْأَعْظَمِ الَّذِي إِذَا دُعِيتَ بِهِ أَجَبْتَ وَإِذَا سُئِلْتَ بِهِ أَعْطَيْتَ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ يَا حَيُّ يَا قَيُّومُ ، يَا حَيُّ يَا قَيُّومُ ، يَا حَيُّ يَا قَيُّومُ ، اللَّهُمَّ أَظِلَّنِي فِي ظِلِّ عَرْشِكَ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّكَ.\nاللَّهُمَّ أَظْهِرْ دِينَكَ عَلَى الدِّينِ كُلِّهُ وَلَوْ كَرِهَ الْمُشْرِكُونَ.\nاللَّهُمَّ يَا مَنْ يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ ، وَيَكْشِفُ السُّوءَ ، اكْشِفِ السُّوءَ عَنْ إِخْوَانِنَا الْأُسَارَى وَالْمَسْجُونِينَ وَالْمُعْتَقَلِينَ ، اللَّهُمَّ افْكُكْ بِقُوَّتِكَ أَسْرَهُمْ ، وَاجْبُرْ بِرَحْمَتِكَ كَسْرَهُمْ ، وَتَوَلَّ بِعِنَايَتِكَ أَمْرَهُمْ ، وَرُدَّهُمْ إِلَى أَهْلِيهِمْ سَالِمِينَ غَانِمِينَ.\nاللَّهُمَّ كُنْ لِلْمُسْلِمِينَ وَالْمُسْتَضْعَفِينَ فِي كُلِّ مَكَانٍ ؛ فَرِّجْ هَمَّهُمْ ، وَنَفِّسْ كَرْبَهُمْ ، وَأَقِلْ عَثْرَتَهُمْ وَتَوَلَّ بِنَفْسِكَ أَمْرَهُمْ.\nاللَّهُمَّ ارْفَعْ رَايَتَهُمْ ، وَاكْبِتْ عَدُوَّهُمْ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ وَحِّدْ صَفَّهُمْ ، وَاجْمَعْ كَلِمَتَهُمْ ، وَرُدَّهُمْ إِلَيْكَ رَدَّاً جَمِيلاً.\nاللَّهُمَّ لَا أَبَرَّ بِهِمْ مِنْكَ ، وَلَا أَرْحَمَ بِهِمْ مِنْكَ، وَلَا أَرْأَفَ بِهِمْ مِنْكَ.. اللَّهُمَّ هُمْ مِنْكَ وَإِلَيكَ.. اللَّهُمَّ فَاجْعَلِ الدَّائِرَةَ لَهُمْ لَا عَلَيْهِمْ وَالنَّصْرَ حَلِيفَهُمْ.. يَا رَبِّ.\nاللَّهُمَّ يَا خَيْرَ مَنْ سُئِلَ ، وَأَجْوَدَ مَنْ أَعْطَى ، وَأَكْرَمَ مَنْ عَفَا ، وَأَعْظَمَ مَنْ غَفَرَ ، وَأَعْدَلَ مَنْ حَكَمَ ، وَأَصْدَقَ مَنْ حَدَّثَ ، وَأَوْفَى مَنْ وَعَدَ ، وَأَبْصَرَ مَنْ رَاقَبَ ، وَأَسْرَعَ مَنْ حَاسَبَ ، وَأَرْحَمَ مَنْ عَاقَبَ ، وَأَحْسَنَ مَنْ خَلَقَ ، وَأَحْكَمَ مَنْ شَرَعَ ، وَأَحَقَّ مَنْ عُبِدَ ، وَأَوْلَى مَنْ دُعِيَ ، وَأَبَرَّ مَنْ أَجَابَ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ الْمَسْأَلَةِ ، وَخَيْرَ الدُّعَاءِ ، وَخَيْرَ النَّجَاحِ ، وَخَيْرَ الْعَمَلِ ، وَخَيْرَ الثَّوَابِ ، وَخَيْرَ الْحَيَاةِ ، وَخَيْرَ الْمَمَاتِ ، وَثَبِّتْنِي ، وَثَقِّلْ مَوَازِينِي ، وَحَقِّقْ إِيمَانِي ، وَارْفَعْ دَرَجَاتِي ، وَتَقَبَّلْ صَلَاتِي ، وَاغْفِرْ خَطِيئَتِي ، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ فَوَاتِحَ الْخَيْرِ ، وَخَوَاتِمَهُ ، وَجَوَامِعَهُ ، وَأَوَّلَهُ ، وَظَاهِرَهُ ، وَبَاطِنَهُ ، وَالدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينَ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ مَا آتِي ، وَخَيْرَ مَا أَفْعَلُ ، وَخَيْرَ مَا أَعْمَلُ ، وَخَيْرَ مَا بَطَنَ ، وَخَيْرَ مَا ظَهَرَ ، وَالدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينَ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ أَنْ تَرْفَعَ ذِكْرِي ، وَتَضَعَ وِزْرِيَ ، وَتُصْلِحَ أَمْرِيَ ، وَتُطَهِّرَ قَلْبِيَ ، وَتُحَصِّنَ فَرْجِيَ ، وَتُنَوِّرَ قَلْبِيَ ، وَتَغْفِرَ لِي ذَنْبِيَ ، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينَ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ أَنْ تُبَارِكَ فِي نَفْسِي ، وَفِي سَمْعِي ، وَفِي بَصَرِي ، وَفِي رُوحِي ، وَفِي خَلْقِي ، وَفِي خُلُقِي ، وَفِي أَهْلِي ، وَفِي مَحْيَايَ ، وَفِي مَمَاتِي ، وَفِي عَمَلِي ، فَتَقَبَّلْ حَسَنَاتِي ، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينَ.\nاللَّهُمَّ لَكَ الْحَمْدُ كُلُّهُ ، اللَّهُمَّ لَا قَابِضَ لِمَا بَسَطْتَ ، وَلَا بَاسِطَ لِمَا قَبَضْتَ ، وَلَا هَادِيَ لِمَنْ أَضْلَلْتَ وَلَا مُضِلَّ لِمَنْ هَدَيْتَ ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا مَانِعَ لِمَا أَعْطَيْتَ ، وَلَا مُقَرِّبَ رَبِّ لِمَا بَاعَدْتَ ، وَلَا مُبَاعِدَ لِمَا قَرَّبْتَ ، اللَّهُمَّ ابْسُطْ عَلَيْنَا مِنْ بَرَكَاتِكَ وَرَحْمَتِكَ وَفَضْلِكَ وَرِزْقِكَ ، اللَّهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ الْمُقِيمَ الَّذِي لَا يَحُولُ وَلَا يَزُولُ ، اللَّهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ يَوْمَ الْعَيْلَةِ وَالْأَمْنِ يَوْمَ الْخَوْفِ ، اللَّهُمَّ إِنِّي عَائِذٌ بِكَ مِنْ شَرِّ مَا أَعْطَيْتَنَا وَشَرِّ مَا مَنَعْتَنَا.\nاللَّهُمَّ حَبِّبْ إِلَيْنَا الْإِيمَانَ وَزَيِّنْهُ فِي قُلُوبِنَا وَكَرِّهْ إِلَيْنَا الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ ، وَاجْعَلْنَا مِنَ الرَّاشِدِينَ ، اللَّهُمَّ تَوَفَّنَا مُسْلِمِينَ ، وَأَحْيِنَا مُسْلِمِينَ ، وَأَلْحِقْنَا بِالصَّالِحِينَ غَيْرَ خَزَايَا وَلَا مَفْتُونِينَ ، اللَّهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِينَ يُكَذِّبُونَ رُسُلَكَ ، وَيَصُدُّونَ عَنْ سَبِيلِكَ ، وَاجْعَلْ عَلَيْهِمْ رِجْزَكَ وَعَذَابَكَ ، اللَّهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِينَ أُوتُوا الْكِتَابَ ، إِلَهَ الْحَقِّ.. آمِينَ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ بِعِلْمِكَ الْغَيْبَ ، وَقُدْرَتِكَ عَلَى الْخَلْقِ ؛ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي ، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ ، وَأَسْأَلُكَ الْقَصْدَ فِي الْغِنَى وَالْفَقْرِ ، وَأَسْأَلُكَ نَعِيماً لَا يَنْفَدُ ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطُعُ ، وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ ، وَالشَّوْقَ إِلَى لِقَائِكَ ، فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ وَلَا فِتْنَةٍ مُضِلَّةٍ ، اللَّهُمَّ زَيِّنَّا بِزِينَةِ الْإِيمَانِ ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ فِعْلَ الْخَيْرَاتِ ، وَتَرْكَ الْمُنْكَرَاتِ ، وَحُبَّ الْمَسَاكِينَ ، وَأَنْ تَغْفِرَ لِي وَتَرْحَمَنِي ، وَإِذَا أَرَدْتَ فِتْنَةَ قَومٍ فَتَوَفَّنِي غَيْرَ مَفْتُونٍ ، وَأَسْأَلُكَ حُبَّكَ ، وَحُبَّ مَنْ يُحِبُّكَ ، وَحُبَّ كُلِّ عَمَلٍ يُقَرِّبُنِي إِلَى حُبِّكَ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهُ ؛ عَاجِلِهِ وَآجِلِهِ ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ ، وَأَعُوذُ بِكَ مِنْ الشَّرِّ كُلِّهُ عَاجِلِهِ وَآجِلِهِ ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ مُحَمَّدٌ ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا اسْتَعَاذَ بِكَ مِنْهُ عَبْدُكَ وَنَبِيُّكَ مُحَمَّدٌ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ ، وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ ، وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ ، وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِي خَيْرًا.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعَاصِيكَ ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ ، وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصَائِبَ الدُّنْيَا ، اللَّهُمَّ مَتِّعْنَا بِأَسْمَاعِنَا ، وَأَبْصَارِنَا ، وَقُوَّاتِنَا مَا أَحْيَيْتَنَا ، وَاجْعَلْهُ الْوَارِثَ مِنَّا ، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا ، وَانْصُرْنَا عَلَى مَنْ عَادَانَا ، وَلَا تَجْعَلْ مُصِيبَتَنَا فِي دِينِنَا وَلَا تَجْعَلْ الدُّنْيَا أَكْبَرَ هَمِّنَا ، وَلَا مَبْلَغَ عِلْمِنَا ، وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ ، وَعَزَائِمَ مَغْفِرَتِكَ ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ ، وَالْفَوْزَ بِالْجَنَّةِ ، وَالنَّجَاةَ مِنَ النَّارِ.\nاللَّهُمَّ لَا تَدَعْ لَنَا ذَنْبًا إِلَّا غَفَرْتَهُ ، وَلَا هَمًّا إِلَّا فَرَّجْتَهُ ، وَلَا دَيْنًا إِلَّا قَضَيْتَهُ ، وَلَا مَرِيضاً إِلَّا شَفَيْتَهُ ، وَلَا مُبْتَلَى إِلَّا عَافَيْتَهُ ، وَلَا ضَالاً إِلَّا هَدَيْتَهُ ، وَلَا غَائِباً إِلَّا رَدَدْتَهُ ، وَلَا مَظْلُوماً إِلَّا نَصَرْتَهُ ، وَلَا أَسِيراً إِلَّا فَكَكْتَهُ ، وَلَا مَيِّتاً إِلَّا رَحِمْتَهُ ، وَلَا حَاجَةً لَنَا فِيهَا صَلَاحٌ وَلَكَ فِيهَا رِضاً إِلَّا قَضَيْتَهَا وَيَسَّرْتَهَا بِفَضْلِكَ يَا أَكْرَمَ الْأَكْرَمِينَ.\nاللَّهُمَّ رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ ، وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ ، وَاهْدِنِي وَيَسِّرِ الْهُدَى إِلَيَّ ، وَانْصُرْنِي عَلَى مَنْ بَغَى عَلَيَّ.\nاللَّهُمَّ رَبِّ اجْعَلْنِي لَكَ شَكَّاراً ، لَكَ ذَكَّاراً ، لَكَ رَهَّاباً ، لَكَ مِطْوَاعاً ، إِلَيْكَ مُخْبِتاً أَوَّاهاً مُنِيباً ، رَبِّ تَقَبَّلْ تَوْبَتِي ، وَاغْسِلْ حَوْبَتِي ، وَأَجِبْ دَعْوَتِي ، وَثَبِّتْ حُجَّتِي ، وَاهْدِ قَلْبِي ، وَسَدِّدْ لِسَانِي ، وَاسْلُلْ سَخِيمَةَ قَلْبِي.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ إِنَّا نَسْأَلُكَ يُسْراً لَيْسَ بَعْدَهُ عُسْرٌ ، وَغِنًى لَيْسَ بَعْدَهُ فَقْرٌ ، وَأَمْناً لَيْسَ بَعْدَهُ خَوْفٌ ، وَسَعَادَةً لَيْسَ بَعْدَهَا شَقَاءٌ.\nاللَّهُمَّ أَلِّفْ بَيْنَ قُلُوبِنَا ، وَأَصْلِحْ ذَاتَ بَيْنِنَا ، وَاهْدِنَا سُبُلَ السَّلَامِ ، وَنَجِّنَا مِنَ الظُّلُمَاتِ إِلَى النُّورِ ، وَجَنِّبْنَا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ ، وَبَارِكْ لَنَا فِي أَسْمَاعِنَا ، وَأَبْصَارِنَا ، وَقُلُوبِنَا ، وَأَزْوَاجِنَا ، وَذُرِّيَّاتِنَا ، وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ ، وَاجْعَلْنَا شَاكِرِينَ لِنِعَمِكَ مُثْنِينَ بِهَا عَلَيْكَ قَابِلِينَ لَهَا وَأَتْمِمْهَا عَلَيْنَا.\nاللَّهُمَّ يَا مُقَلِّبَ الْقُلُوبِ وَالْأَبْصَارِ ، ثَبِّتْ قُلُوبَنَا عَلَى طَاعَتِكَ ، وَلَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا ، وَلَا تَفْتِنَّا فِي دِينِنَا ، وَاجْعَلْ يَوْمَنَا خَيْراً مِنْ أَمْسِنَا ، وَاجْعَلْ غَدَنَا خَيْراً مِنْ يَوْمِنَا ، وَاجْعَلْ خَيْرَ أَعْمَارِنَا أَوَاخِرَهَا ، وَخَيْرَ أَعْمَالِنَا خَوَاتِيمَهَا ، وَخَيْرَ أَيَّامِنَا يَوْمَ نَلْقَاكَ وَأَنْتَ رَاضٍ عَنَّا.\nاللَّهُمَّ أَنْتَ الَّذِي خَلَقْتَنِي فَأَنْتَ تَهْدِينِ ، وَأَنْتَ الَّذِي تُطْعِمُنِي وَتَسْقِينِ ، وَإِذَا مَرِضْتُ فَأَنْتَ تَشْفِينِ ، وَأَنْتَ الَّذِي تُمِيتُنِي ثُمَّ تُحْيِينِ ، وَأَنْتَ الَّذِي أَطْمَعُ أَنْ يَغْفِرَ لِي خَطِيئَتِي يَوْمَ الدِّينِ ، رَبِّ هَبْ لِي حُكْماً وَأَلْحِقْنِي بِالصَّالِحِينَ ، وَاجْعَلْ لِي لِسَانَ صِدْقٍ فِي الْآخِرِينَ ، وَاجْعَلْنِي مِنْ وَرَثَةِ جَنَّةِ النَّعِيمِ ، وَاغْفِرْ لِآبَائِنَا وَأُمَّهَاتِنَا مِنَ الْمُسْلِمِينَ وَلَا تُخْزِنِي يَوْمَ يُبْعَثُونَ ، يَوْمَ لَا يَنْفَعُ مَالٌ وَلَا بَنُونَ ، إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ.\nاللَّهُمَّ احْفَظْنِي بِالْإِسْلَامِ قَائِماً ، وَاحْفَظْنِي بِالْإِسْلَامِ قَاعِداً ، وَاحْفَظْنِي بِالْإِسْلَامِ رَاقِداً ، وَلَا تُشْمِتْ بِي عَدُوّاً وَلَا حَاسِداً.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ كُلِّ خَيْرٍ خَزَائِنُهُ بِيَدِكَ ، وَأَعُوذُ بِكَ مِنْ كُلِّ شَرٍّ خَزَائِنُهُ بِيَدِكَ.\nاللَّهُمَّ يَا ذَا الْحَبْلِ الشَّدِيدِ ، وَالْأَمْرِ الرَّشِيدِ ، أَسْأَلُكَ الْأَمْنَ يَوْمَ الْوَعِيدِ ، وَالْجَنَّةَ دَارَ الْخُلُودِ ، مَعَ الْمُقَرَّبِينَ الشُّهُودِ ، الرُّكَّعِ السُّجُودِ ، الْمُوفِينَ بِالْعُهُودِ ، إِنَّكَ رَحِيمٌ وَدُودٌ ، وَإِنَّكَ تَفْعَلُ مَا تُرِيدُ.\nاللَّهُمَّ اجْعَلْنَا هَادِينَ مُهْتَدِينَ ، غَيْرَ ضَالِّينَ وَلَا مُضِلِّينَ ، سِلْماً لِأَوْلِيَائِكَ ، وَحَرْباً عَلَى أَعْدَائِكَ ، نُحِبُّ بِحُبِّكَ مَنْ أَحَبَّكَ ، وَنُعَادِي بِعَدَاوَتِكَ مَنْ خَالَفَكَ.اللَّهُمَّ هَذَا الدُّعَاءُ وَمِنْكَ الْإِجَابَةُ ، اللَّهُمَّ هَذَا الْجُهْدُ وَعَلَيْكَ التُّكْلَانُ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَاناً لَا يَرْتَدُّ ، وَنَعِيماً لَا يَنْفَدُ ، وَمُرَافَقَةَ نَبِيِّكَ مُحَمَّدٍ فِي أَعْلَى جَنَّةِ الْخُلْدِ.\nاللَّهُمَّ آتِنِي الْحِكْمَةَ الَّتِي مَنْ أُوتِيَهَا فَقَدْ أُوتِيَ خَيْراً كَثِيراً.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ.\nاللَّهُمَّ ارْحَمْنِي ، فَأَنْتَ خَيْرُ الرَّاحِمِينَ ، وَارْزُقْنِي ، فَأَنْتَ خَيْرُ الرَّازِقِينَ ، وَاغْفِرْ لِي فَأَنْتَ خَيْرُ الْغَافِرِينَ ، وَانْصُرْنِي ، فَأَنْتَ خَيْرُ النَّاصِرِينَ.\nاللَّهُمَّ رَحْمَتَكَ أَرْجُو فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ ، لَا إِلَهَ إِلَّا أَنْتَ.\nاللَّهُمَّ زِدْنَا وَلَا تَنْقُصْنَا ، وَأَكْرِمْنَا وَلَا تُهِنَّا ، وَأَعْطِنَا وَلَا تَحْرِمْنَا ، وَآثِرْنَا وَلَا تُؤْثِرْ عَلَيْنَا ، وَأَرْضِنَا وَارْضَ عَنَّا.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ عِيشَةً نَقِيَّةً ، وَمِيتَةً سَوِيَّةً ، وَمَرَدّاً غَيْرَ مُخْزٍ وَلَا فَاضِحٍ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَى وَالِدَيَّ ، وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَدْخِلْنِي بِرَحْمَتِكَ فِي عِبَادِكَ الصَّالِحِينَ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ وَالْمُعَافَاةَ فِي الدُّنْيَا وَالْآخِرَةِ.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى ، وَالتُّقَى ، وَالْعَفَافَ وَالْغِنَى.\nاللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نَافِعًا ، وَرِزْقاً طَيِّباً ، وَعَمَلاً مُتَقَبَّلاً.\nاللَّهُمَّ اغْفِرْ لِي ، وَاهْدِنِي وَارْزُقْنِي ، وَعَافِنِي ، أَعُوذُ بِاللَّهِ مِنْ ضِيقِ الْمَقَامِ يَوْمَ الْقِيَامَةِ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ قِنِي شَرَّ نَفْسِي ، وَاعْزِمْ لِي عَلَى أَرْشَدِ أَمْرِي ، اللَّهُمَّ اغْفِرْ لِي مَا أَسْرَرْتُ ، وَمَا أَعْلَنْتُ وَمَا أَخْطَأْتُ ، وَمَا عَمَدْتُ ، وَمَا عَلِمْتُ ، وَمَا جَهِلْتُ.\nاللَّهُمَّ أَكْثِرْ مَالِي ، وَوَلَدِي ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَنِي ، وَأَطِلْ حَيَاتِي عَلَى طَاعَتِكَ ، وَأَحْسِنْ عَمَلِي وَاغْفِرْ لِي.\nاللَّهُمَّ اسْتُرْ عَوَرَاتِي ، وَآمِنْ رَوْعَاتِي ، وَاحْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي ، وَعَنْ يَمِينِي وَعَنْ شِمَالِي ، وَمِنْ فَوْقِي ، وَأَعُوذُ بِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.\nاللَّهُمَّ أَكْرِمْنِي وَلَا تُهِنِّي ، وَأَعْطِنِي وَلَا تَحْرِمْنِي ، وَزِدْنِي وَلَا تَنْقُصْنِي ، وَآثِرْنِي وَلَا تُؤْثِرْ عَلَيَّ ، وَارْضَ عَنِّي وَأَرْضِنِي.\nاللَّهُمَّ افْتَحْ لَنَا فَتْحاً مُبِيناً ، وَاهْدِنَا صِرَاطاً مُسْتَقِيماً ، وَانْصُرْنَا نَصْراً عَزِيزاً، وَأَتِمَّ عَلَيْنَا نِعْمَتَكَ ، وَأَنْزِلْ فِي قُلُوبِنَا سَكِينَتَكَ ، وَانْشُرْ عَلَيْنَا فَضْلَكَ وَرَحْمَتَكَ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ أَعِنَّا عَلَى شَهَوَاتِ أَنْفُسِنَا، وَقَسْوَةِ قُلُوبِنَا ، وَضَعْفِ إِرَادَتِنَا ، وَلَا تَكِلْنَا إِلَى أَنْفُسِنَا وَلَا إِلَى أَحَدٍ غَيْرِكَ.\nاللَّهُمَّ لَا تَكِلْنَا إِلَى أَنْفُسِنَا طَرْفَةَ عَيْنٍ وَلَا أَقَلَّ مِنْ ذَلِكَ.\nاللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ.\nاللَّهُمَّ اشْغَلْ قُلُوبَنَا بِحُبِّكَ ، وَأَلْسِنَتَنَا بِذِكْرِكَ ، وَأَبْدَانِنَا بِطَاعَتِكَ ، وَعُقُولَنَا بِالتَّفَكُّرِ فِي خَلْقِكَ وَالتَّفَقُّهِ فِي دِينِكَ.\nاللَّهُمَّ اشْفِ مَرْضَانَا ، وَارْحَمْ مَوْتَانَا ، وَعَافِ مُبْتَلَانَا ، وَفُكَّ أَسْرَنَا ، وَاجْبُرْ كَسْرَنَا.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ أَطْعِمْنَا مِنْ جُوعٍ ، وَآمِنَّا مِنْ خَوْفٍ، وَقَوِّنَا مِنْ ضَعْفٍ ، وَعَلِّمْنَا مِنْ جَهَالَةٍ، وَأَنْقِذْنَا مِنْ ضَلَالَةٍ.\nاللَّهُمَّ اخْتِمْ بِالصَّالِحَاتِ أَعْمَالَنَا ، وَبِالسَّعَادَةِ آجَالَنَا ، وَبَلِّغْنَا مِمَّا يُرْضِيكَ آمَالَنَا.\nاللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي ، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي, وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي ، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ.\nاللَّهُمَّ اجْعَلْ خَيْرَ عُمْرِي أَوَاخِرَهُ ، وَخَيْرَ عَمَلِي خَوَاتِمَهُ ، وَخَيْرَ أَيَّامِي يَوْمَ لِقَاكَ.\nاللَّهُمَّ احْفَظْنِي بِالْإِسْلَامِ قَائِماً ، وَاحْفَظْنِي بِالْإِسْلَامِ قَاعِداً ، وَاحْفَظْنِي بِالْإِسْلَامِ رَاقِداً ، وَلَا تُشْمِتْ بِيَ عَدُوًّا وَلَا حَاسِدًا.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"},{"t":"اللَّهُمَّ أَحْيِنَا مُسْلِمِينَ ، وَتَوَفَّنَا مُسْلِمِينَ ، وَأَلْحِقْنَا بِالصَّالِحِينَ.\nاللَّهُمَّ أَبْرِمْ لِهَذِهِ الْأُمَّةِ أَمْرَ رُشْدٍ ، يُعَزُّ فِيهِ أَهْلُ طَاعَتِكَ ، وَيُذَلُّ فِيهِ أَهْلُ مَعْصِيَتِكَ ، وَيُؤْمَرُ فِيهِ بِالْمَعْرُوفِ ، وَيُنْهَى فِيهِ عَنِ الْمُنْكَرِ.\nاللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى عَبْدِكَ وَرَسُولِكَ مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ أَجْمَعِينَ.","c":1,"s":"أدعية جامعة من القرآن والسنة وغيرها","f":"gen","w":"أدعية عامة جمعها الموقع؛ فيها المأثور وغير المأثور، وليست أحاديث بنصها"}]},{"k":"khatm","ar":"دعاء ختم القرآن","en":"Completing the Quran","items":[{"t":"اللَّهُمَّ ارْحَمْنِي بِالْقُرْآنِ وَاجْعَلْهُ لِي إِمَاماً وَنُوراً وَهُدًى وَرَحْمَةً *\nاللَّهُمَّ ذَكِّرْنِي مِنْهُ مَا نَسِيتُ وَعَلِّمْنِي مِنْهُ مَا جَهِلْتُ وَارْزُقْنِي تِلَاوَتَهُ آنَاءَ اللَّيْلِ وَأَطْرَافَ النَّهَارِ وَاجْعَلْهُ لِي حُجَّةً يَا رَبَّ الْعَالَمِينَ *\nاللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ *\nاللَّهُمَّ اجْعَلْ خَيْرَ عُمْرِي آخِرَهُ وَخَيْرَ عَمَلِي خَوَاتِمَهُ وَخَيْرَ أَيَّامِي يَوْمَ أَلْقَاكَ فِيهِ *\nاللَّهُمَّ إِنِّي أَسْأَلُكَ عِيشَةً هَنِيَّةً وَمِيتَةً سَوِيَّةً وَمَرَدًّا غَيْرَ مُخْزٍ وَلَا فَاضِحٍ *\nاللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ الْمَسْأَلَةِ وَخَيْرَ الدُّعَاءِ وَخَيْرَ النَّجَاحِ وَخَيْرَ الْعِلْمِ وَخَيْرَ الْعَمَلِ وَخَيْرَ الثَّوَابِ وَخَيْرَ الْحَيَاةِ وَخَيْرَ الْمَمَاتِ وَثَبِّتْنِي وَثَقِّلْ مَوَازِينِي وَحَقِّقْ إِيمَانِي وَارْفَعْ دَرَجَتِي وَتَقَبَّلْ صَلَاتِي وَاغْفِرْ خَطِيئَاتِي وَأَسْأَلُكَ الْعُلَا مِنَ الْجَنَّةِ *\nاللَّهُمَّ إِنِّي أَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ وَعَزَائِمِ مَغْفِرَتِكَ وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ وَالْفَوْزَ بِالْجَنَّةِ وَالنَّجَاةَ مِنَ النَّارِ *\nاللَّهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُورِ كُلِّهَا، وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآخِرَةِ *\nاللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعْصِيَتِكَ وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهَا جَنَّتَكَ وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصَائِبَ الدُّنْيَا وَمَتِّعْنَا بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّتِنَا مَا أَحْيَيْتَنَا وَاجْعَلْهُ الْوَارِثَ مِنَّا وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا وَانْصُرْنَا عَلَى مَنْ عَادَانَا وَلَا تَجْعَلْ مُصِيبَتَنَا فِي دِينِنَا وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا وَلَا مَبْلَغَ عِلْمِنَا وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا *\nاللَّهُمَّ لَا تَدَعْ لَنَا ذَنْبًا إِلَّا غَفَرْتَهُ وَلَا هَمًّا إِلَّا فَرَّجْتَهُ وَلَا دَيْنًا إِلَّا قَضَيْتَهُ وَلَا حَاجَةً مِنْ حَوَائِجِ الدُّنْيَا وَالْآخِرَةِ إِلَّا قَضَيْتَهَا يَا أَرْحَمَ الرَّاحِمِينَ *\nرَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا وَنَبِيِّنَا مُحَمَّدٍ وَعَلَى آلِهِ وَأَصْحَابِهِ الْأَخْيَارِ وَسَلَّمَ تَسْلِيمًا كَثِيراً.","c":1,"s":"يُنسب إلى النبي ﷺ","f":"weak","w":"لا يثبت عن النبي ﷺ — ضعيف الإسناد"}]}];
